# -*- coding: utf-8 -*-
"""
風雲社 · 通关云点查询器（桌面版）
=================================================================
独立窗口应用。实时定位你当前所在服务器，认出地图，
显示该图各关卡的通关云点（rankPasses）。

定位方式（两条通道，自动择优）：
  1) fys 广播文件  C:\\Users\\1\\AppData\\Local\\fys\\fys.broadcast.assistant.txt
     —— 能给到「当前关卡」，但实测进服后不保证刷新
  2) Steam 连接日志 <Steam>\\logs\\console_log.txt 里最后一次 +connect 地址
     + 对该地址做 A2S 查询 —— 稳定拿到服务器名 / 地图 / 在线人数，但没有关卡号

架构说明（重要）：
  窗口用 pywebview(WebView2) 原生渲染，但 *不* 依赖它的 JS 桥——
  JS 桥在 PyInstaller 打包后曾出现注入失败且难以定位。
  这里统一走本机回环 HTTP：
      GET /api/status          -> 当前地图/关卡/通关云点
      GET /api/ctl?do=min|maxtoggle|refresh|sync|ov* -> 窗口/覆盖控制
  因此无论是否打包成 exe，行为完全一致。

启动：
    双击 run_app.bat  或  python fys_reward_app.py
参数：
    --browser   不开原生窗口，直接用系统默认浏览器
    --port N    指定本地端口（默认固定 8777；被别的程序占用时才自动换）
"""
