# GUI 进程（打包后 console=False，本进程没有控制台）一旦调用控制台程序
# （taskkill / netstat / cmd…），Windows 会**为子进程新建一个控制台窗口**——
# 用户看到的就是切换覆盖布局时闪出一个标题为 C:\Windows\SYSTEM32\taskkill.exe 的黑框。
# 所有运行时的 subprocess 调用都必须带 CREATE_NO_WINDOW（对 GUI 子进程无副作用）。
_NO_WINDOW = 0x08000000            # subprocess.CREATE_NO_WINDOW

try:
    sys.stdout.reconfigure(encoding="utf-8")
except Exception:
    pass    # 静默合理：老终端不支持 UTF-8 也得照常跑

