WIN_W, WIN_H = 1330, 720

LOG_PATH = os.path.join(BASE_DIR, "data", "startup.log")


def log(msg):
    line = "%s  %s" % (time.strftime("%Y-%m-%d %H:%M:%S"), msg)
    try:
        os.makedirs(os.path.dirname(LOG_PATH), exist_ok=True)
        # 简单轮转：超过 512KB 就归档为 startup.old.log（覆盖旧的），日志不再无限增长
        try:
            if os.path.getsize(LOG_PATH) > 512_000:
                os.replace(LOG_PATH, LOG_PATH.replace(".log", ".old.log"))
        except OSError:
            pass    # 静默合理：轮转失败大不了这轮不轮转
        with open(LOG_PATH, "a", encoding="utf-8") as fh:
            fh.write(line + "\n")
    except OSError:
        pass
    try:
        print(line, flush=True)
    except Exception:
        pass


def log_size():
    """运行日志当前体积（字节）；读不到就返回 None。设置页「关于」卡显示用。"""
    try:
        return os.path.getsize(LOG_PATH)
    except OSError:
        return None


