import ui_page

# 页面模板抽到 ui_page.py（可爱主题 + 可收缩侧栏），改样式只动那个文件
# 版本号就地注入标题栏（侧栏「云朵小铺」旁），首屏即可见、不依赖接口
def _boot_theme():
    """首屏主题（构建页面时读保存的偏好；失败/未存 → 默认 E）。

    页面 HTML 在模块导入时构建缓存，load_uiprefs() 定义在其后——这里直接
    读 data/ui_prefs.json 一把，逻辑与 load_uiprefs 保持一致（读失败给默认）。
    """
    try:
        with open(os.path.join(BASE_DIR, "data", "ui_prefs.json"),
                  "r", encoding="utf-8") as fh:
            d = json.load(fh)
        t = str((d if isinstance(d, dict) else {}).get("theme") or "E").strip().upper()[:1]
        return t if t in ("E", "F", "G", "H", "N") else "E"
    except Exception:                                          # noqa: BLE001
        return "E"


HTML = ui_page.build_page(APP_VER, theme=_boot_theme())


# ── 地图实体预览页（3D 视图，打包时随 exe 内置；复用 ui_page 的资源定位） ──
PREVIEW_FILE = "preview3d.html"
_PREVIEW_CACHE = {"path": None, "mtime": 0.0, "data": None}


def preview_path():
    """预览页文件位置。优先 exe / 源码目录下的同名文件（便于单独替换更新），
    再退回打包内置的那份。"""
    for p in (os.path.join(BASE_DIR, PREVIEW_FILE),
              ui_page._resource_path(PREVIEW_FILE)):
        if p and os.path.exists(p):
            return p
    return ""


_ROOT_ETAG = {"v": None}


def root_etag():
    """主页 ETag（内容决定，进程内算一次）。

    大资源（主页 ~1MB、预览页 ~14MB、terr/*.bin）以前一律 Cache-Control: no-store，
    浏览器每次进「地图实体预览」都得重新下 14MB。改成 Cache-Control: no-cache + ETag，
    命中就回 304（无 body），本地回环下也省掉一次 14MB 的拷贝。
    """
    if _ROOT_ETAG["v"] is None:
        b = HTML.encode("utf-8")
        _ROOT_ETAG["v"] = '"root-%d-%08x"' % (len(b), zlib.crc32(b))
    return _ROOT_ETAG["v"]


# ── 预览壳云端按需分发（v2.0 起）────────────────────────────────────
# preview3d.html 约 16.3MB，是 667 张僵尸逃跑图的实体数据。不再随发行包分发：
# 首次打开预览时由本服务从云端取一份落到 exe 旁，之后就是本地读取（秒开），
# 断网也能看。要发离线完整包，打包时加 --full-pv 即可。
def _cloud_env(key, default=""):
    """云端基址读取（v2.14 起服务器停用 → 全部默认空 = 纯本地 / 官方源直连）。

    留空时对应能力**直接短路**：不发请求、不等超时、不写日志噪音。
    将来若又有静态托管（GitHub Pages / Gitee / 自建），设同名环境变量即可恢复，
    不需要改代码；填空串等价于关闭。
    """
    v = os.environ.get(key)
    return (default if v is None else v).strip().rstrip("/")


# 预览壳云端源（2026-11-16 恢复云端按需分发，托管在 GitHub 主仓库 pv/ 目录）。
# 多源逐试（与 update_bases / terr_cdn_bases 同一套路），gh-proxy 实测最快放首位；
# FYS_PV_URL 环境变量可整体覆盖（逗号分隔多个源）。
PV_BASES_DEFAULT = (
    "https://gh-proxy.com/https://raw.githubusercontent.com/emmmmm0/FYS-Reward/main/pv,"
    "https://raw.githubusercontent.com/emmmmm0/FYS-Reward/main/pv,"
    "https://cdn.jsdelivr.net/gh/emmmmm0/FYS-Reward@main/pv,"
    "https://ghproxy.net/https://raw.githubusercontent.com/emmmmm0/FYS-Reward/main/pv"
)
PV_URLS = [u for u in _cloud_env("FYS_PV_URL", PV_BASES_DEFAULT).split(",") if u]
PV_URL = PV_URLS[0] if PV_URLS else ""     # 兼容旧引用：非空即视为「有云端壳可拉」
PV_TIMEOUT = 180.0
PV_NEED_MB = 16.3


def _pv_open(suffix="", method="GET", timeout=6):
    """按 PV_URLS 逐源请求预览壳相关文件，返回第一个成功的响应对象。

    与 terr_fetch / update_check 同思路：绕开系统代理，源失败（DNS 污染 /
    限流 403 / 超时）自动换下一个；全部失败抛最后一个异常（保留 code 属性，
    上层靠它区分 404 / 网络）。"""
    import urllib.request
    op = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    last = None
    for base in PV_URLS:
        try:
            req = urllib.request.Request(base + suffix, method=method)
            return op.open(req, timeout=timeout)
        except Exception as e:                                 # noqa: BLE001
            last = e
            continue
    raise last or RuntimeError("无预览壳云端源")
