def update_bases():
    """更新清单的基础地址列表（逗号/换行分隔，按顺序尝试）。"""
    raw = os.environ.get("FYS_UPDATE_BASE") or UPDATE_BASE_DEFAULT
    out = []
    for part in re.split(r"[,\s]+", raw or ""):
        p = part.strip().rstrip("/")
        if p and p not in out:
            out.append(p)
    return out


