# ── 地图译名云端热更（2026-09-28 起）────────────────────────────────────
# 译名是会持续补充的（新图上线、发现更好的叫法），若每补几条就要发一次版太笨重。
# 这里从服务器拉一份 mapnames.json（约 30KB）落到**程序旁** data\mapnames_remote.json，
# mapnames.py 把它当作优先级仅次于「用户自定义」的查表层 —— 换服务器上那份即可生效。
# 拉取失败一律静默（继续用上一份 + 内置表），不影响任何功能。
MAPNAMES_URL = _cloud_env("FYS_MAPNAMES_URL")
MAPNAMES_TTL = 6 * 3600.0
_MN_STATE = {"at": 0.0, "ok": False, "n": 0}


def mapnames_tick(force=False):
    """后台拉一次云端译名表（同一进程内最快 6 小时一次），从不阻塞调用方。"""
    now = time.time()
    if not MAPNAMES_URL:           # 离线版：用本地 data\mapnames_remote.json + 内置表
        _MN_STATE["at"] = now
        return dict(_MN_STATE)
    if not force and now - _MN_STATE["at"] < MAPNAMES_TTL:
        return dict(_MN_STATE)
    _MN_STATE["at"] = now

    def work():
        try:
            import urllib.request
            op = urllib.request.build_opener(urllib.request.ProxyHandler({}))
            raw = op.open(MAPNAMES_URL, timeout=8).read()
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or len(obj) < 50:
                log("mapnames: 云端表内容异常，忽略本次")
                return
            d = os.path.join(BASE_DIR, "data")
            os.makedirs(d, exist_ok=True)
            dst = os.path.join(d, "mapnames_remote.json")
            tmp = dst + ".part"
            with open(tmp, "wb") as fh:
                fh.write(raw)
            os.replace(tmp, dst)          # 原子替换：不会读到半截文件
            _MN_STATE.update(ok=True, n=len(obj))
            log("mapnames: 云端译名表已更新 %d 条" % len(obj))
        except Exception as e:                                 # noqa: BLE001
            log("mapnames: 拉取失败（沿用上一份）%r" % (e,))

    threading.Thread(target=work, daemon=True, name="mapnames-fetch").start()
    return dict(_MN_STATE)


def mapnames_loop():
    """启动后台译名更新循环：起来后 6 秒首拉，之后每 6 小时一次。"""
    time.sleep(6)
    mapnames_tick(force=True)
    while True:
        time.sleep(MAPNAMES_TTL)
        mapnames_tick(force=True)


# ── 上游数据变更后台定时检测（v2.5 起）─────────────────────────────────
# 之前只在「启动」和「手动立即同步」两刻比对上游；托盘常驻软件可能连开几天，
# 期间上游推了新提交也不会被告知。这里每 30 分钟静默拉一次上游并比对，
# 有累计未读变更就弹首页横幅（/api/status 轮询带出）。
# 与手动同步的关键区别：① 只比对、不覆盖本地缓存（否则横幅只显示增量）；
# ② 空 diff 时保留用户还没看过的未读提醒（_write_diff 的 force=False 分支）。
REPO_CHECK_TTL = 30 * 60.0
_REPO_CHECK_STATE = {"at": 0.0, "ok": False, "total": 0}


def repo_check_tick(force=False):
    """后台拉一次上游并比对（同进程内最快 30 分钟一次），用于「官方数据有更新」横幅。

    force 只用于绕过 TTL 冷却（首查 / 测试）；真正下发给 build_index 的永远是
    无覆盖的 auto=True，绝不传 force。
    """
    now = time.time()
    if not force and now - _REPO_CHECK_STATE["at"] < REPO_CHECK_TTL:
        return dict(_REPO_CHECK_STATE)
    _REPO_CHECK_STATE["at"] = now

    def work():
        try:
            import build_index
            build_index.build(auto=True)        # 只比对、不覆盖缓存
            # 把落盘的 diff 同步进内存 STATE，否则 /api/status 轮询读不到新横幅
            if State.engine is not None:
                State.engine.refresh_diff()
            d = (getattr(State.engine, "STATE", None) or {}).get("diff") or {}
            tot = (d.get("counts") or {}).get("total", 0)
            _REPO_CHECK_STATE.update(ok=True, total=tot)
            log("repo_check: 上游比对完成（diff total=%s）" % tot)
            # 自动同步（v2.14）：检出变更且开着「自动同步」→ 直接应用，不再等
            # 用户点「立即同步」。应用走 force 路径：snapshot_prev 留对比基准、
            # load_state 抬 dgen 让前端原地刷新、台账记一条；完事 diff_mark_seen。
            if (tot > 0 and State.engine is not None
                    and load_uiprefs().get("upd_autosync", True)
                    and not State.sync.get("running")):
                log("repo_check: 自动同步开始（%s 项上游变更）" % tot)
                _sync_worker()
        except Exception as e:                 # noqa: BLE001
            _REPO_CHECK_STATE.update(ok=False)
            log("repo_check: 上游比对失败（沿用上一份）%r" % (e,))

    threading.Thread(target=work, daemon=True, name="repo-check").start()
    return dict(_REPO_CHECK_STATE)


def repo_check_loop():
    """启动后台上游变更检测循环：起来后 30 秒首查，之后每 30 分钟一次。"""
    time.sleep(30)
    repo_check_tick(force=True)
    while True:
        time.sleep(REPO_CHECK_TTL)
        repo_check_tick(force=True)


