def terr_dir(make=False):
    """地形缓存目录（exe 旁的 terr\\）。FYS_TERR_DIR 可改（回归测试用临时目录）。"""
    d = os.environ.get("FYS_TERR_DIR") or os.path.join(BASE_DIR, "terr")
    if make:
        try:
            os.makedirs(d, exist_ok=True)
        except OSError as e:                                   # noqa: BLE001
            log("terr: 建缓存目录失败 %r" % (e,))
            return None
    return d


# ─── 地形分包：本地优先，缺的按需从 GitHub 拉（2026-11-15 用户定的方案） ───
# 安装包只带预览壳，地形不进包（省 284MB）；玩家第一次点开某张图时，若本机没有
# 这一张的 .bin，就按本图工坊 ID 从静态托管单文件下载并落盘缓存（中位 0.4MB）。
# 来源优先级：环境变量 FYS_TERR_CDN > data\terr_cdn.txt > 下面这个默认地址。
# 置空 = 关闭回源（纯离线行为）。换成 Gitee/自己的服务器只改这一行或那个文本文件。
# 地形分包托管（多个地址按顺序试：jsDelivr 是 GitHub 的国内可用 CDN，
# 直连 raw.githubusercontent 在国内经常超时，所以放最后兜底）
TERR_CDN_DEFAULT = ("https://gh-proxy.com/https://raw.githubusercontent.com/emmmmm0/fys-terr/main/terr,"
                    "https://cdn.jsdelivr.net/gh/emmmmm0/fys-terr@main/terr,"
                    "https://ghproxy.net/https://raw.githubusercontent.com/emmmmm0/fys-terr/main/terr,"
                    "https://raw.githubusercontent.com/emmmmm0/fys-terr/main/terr")
_TERR_LOCKS = {}
_TERR_GUARD = threading.Lock()
_TERR_FAIL = {}                    # 文件名 → 失败时间（10 分钟内不重试，免得每次点都等超时）
TERR_FAIL_TTL = 600.0
TERR_MAX_MB = 24                   # 防御：单包超过这个大小直接放弃（正常最大 0.7MB）


def terr_cdn_bases():
    """地形分包的基础地址列表（按顺序尝试，空列表 = 不回源）。

    来源：环境变量 FYS_TERR_CDN > data\terr_cdn.txt（可写多行）> 内置默认。
    多个地址用逗号或换行分隔，例如 jsDelivr 优先、GitHub 直连兜底。
    """
    txt = ""
    try:
        with io.open(os.path.join(BASE_DIR, "data", "terr_cdn.txt"), "r", encoding="utf-8") as fh:
            txt = "\n".join(ln.strip() for ln in fh.read().splitlines()
                            if ln.strip() and not ln.strip().startswith("#"))
    except OSError:
        pass
    raw = (os.environ.get("FYS_TERR_CDN") or txt or TERR_CDN_DEFAULT)
    out = []
    for part in re.split(r"[,\s]+", raw or ""):
        p = part.strip().rstrip("/")
        if p and "OWNER/REPO" not in p and p not in out:
            out.append(p)
    return out


def terr_cdn():
    """兼容旧调用：返回首选地址（没有就空串）。"""
    b = terr_cdn_bases()
    return b[0] if b else ""


def terr_fetch(name):
    """取单张地形分包：本地命中直接读；没有就从托管按需下载并缓存。

    返回 (data, err)：err=None 成功；'nodir' 目录建不了；'miss' 远端未收录
    （404，10 分钟内不再重试）；'offline' 没配来源 / 网络失败（可重试）。
    """
    d = terr_dir(make=True)
    if not d:
        return None, "nodir"
    fp = os.path.join(d, name)

    def _read_local():
        try:
            with open(fp, "rb") as fh:
                return fh.read()
        except OSError:
            return None

    got = _read_local()
    if got is not None:
        return got, None
    # .js 是旧版 file:// 兜底格式，托管上只放 .bin
    if name.endswith(".js"):
        return None, "miss"
    bases = terr_cdn_bases()
    if not bases:
        return None, "nocdn"
    with _TERR_GUARD:
        fail_at = _TERR_FAIL.get(name)
        if fail_at and (time.time() - fail_at) < TERR_FAIL_TTL:
            return None, "miss"
        lk = _TERR_LOCKS.get(name)
        if lk is None:
            lk = _TERR_LOCKS[name] = threading.Lock()
    with lk:
        got = _read_local()          # 等锁期间别人可能已经下好了
        if got is not None:
            return got, None
        tmp = fp + ".part"
        t0 = time.time()
        last_err = "offline"
        # 总预算 30s（2026-11-16）：原来每源 25s、4 源串行最坏 100s 才答复，
        # 镜像半残的晚上玩家点一张缺地形的图要干等一分半。预算只在「换源」时
        # 检查，不会切断正在进行中的下载；超预算按网络失败答复（可重试）。
        deadline = t0 + 30.0
        try:
            for base in bases:
                if time.time() > deadline:
                    break
                url = base + "/" + urllib.parse.quote(name)
                try:
                    req = urllib.request.Request(url, headers={"User-Agent": "FYS-Reward"})
                    with urllib.request.urlopen(req, timeout=12) as r:
                        data = r.read(TERR_MAX_MB * 1048576 + 1)
                    if not data:
                        raise ValueError("空响应")
                    if len(data) > TERR_MAX_MB * 1048576:
                        raise ValueError("分包过大（>%dMB）" % TERR_MAX_MB)
                    with open(tmp, "wb") as fh:
                        fh.write(data)
                    os.replace(tmp, fp)
                    _TERR_STAT_CACHE["t"] = 0.0
                    log("[地形] 已下载 %s（%.0f KB，%.1f 秒，来源 %s）"
                        % (name, len(data) / 1024.0, time.time() - t0,
                           urllib.parse.urlsplit(url).hostname))
                    return data, None
                except urllib.error.HTTPError as e:
                    if e.code in (403, 404):
                        last_err = "miss"
                        continue          # 这个源没有，换下一个（CDN 缓存/镜像差异）
                    last_err = "offline"
                    log("[地形] %s 下载失败：HTTP %s" % (name, e.code))
                    continue
                except Exception as e:                     # noqa: BLE001
                    last_err = "offline"
                    log("[地形] %s 下载失败：%r" % (name, e))
                    continue
            _TERR_FAIL[name] = time.time()
            if last_err == "miss":
                log("[地形] 所有托管都没有 %s，10 分钟内不再重试" % name)
                return None, "miss"
            return None, "offline"
        finally:
            try:
                if os.path.exists(tmp):
                    os.remove(tmp)
            except OSError:
                pass


def terr_stat(force=False):
    """地形缓存占用 {count, mb, total}。结果缓存 5 秒（进 3D 页每次都会问）。"""
    now = time.time()
    if not force and _TERR_STAT_CACHE["v"] and now - _TERR_STAT_CACHE["t"] < 5:
        return _TERR_STAT_CACHE["v"]
    d = terr_dir()
    n = 0
    size = 0
    if d and os.path.isdir(d):
        try:
            for f in os.listdir(d):
                if f.endswith(".bin"):
                    n += 1
                    size += os.path.getsize(os.path.join(d, f))
        except OSError:
            pass
    v = {"count": n, "mb": round(size / 1048576.0, 1),
         "total": max(TERR_TOTAL, n)}   # 随包分发时实际件数就是上限，别显示 700/643
    _TERR_STAT_CACHE.update(t=now, v=v)
    return v


def terr_clear():
    """清空地形缓存（只删缓存目录下的 .bin/.part，不碰其它文件）。"""
    d = terr_dir()
    n = 0
    if d and os.path.isdir(d):
        for f in os.listdir(d):
            if f.endswith(".bin") or f.endswith(".part"):
                try:
                    os.remove(os.path.join(d, f))
                    n += 1
                except OSError:
                    pass
    _TERR_STAT_CACHE["t"] = 0.0
    log("terr: 已清理 %d 个缓存分包" % n)
    return {"ok": True, "removed": n, **terr_stat(force=True)}


def _ver_key(v):
    """'v2.4.1' → (2, 4, 1)。解析不了返回 None（当作无法比较、不提示更新）。

    ⚠ 这里曾经只取前两段（`^v(\\d+)(?:\\.(\\d+))?`），于是
        v2.4.2 与 v2.4.1 都变成 (2, 4) —— **第三段及以后被整段丢掉**，
        `nk > ck` 恒为 False，v2.4 → v2.4.1 → v2.4.2 这条线上的用户
        **永远收不到更新提示**（界面显示「已是最新」，服务端其实早就换新了）。
    现在按「点分段全部取出、逐段比数值」，段数不同时短的那侧补 0
    （v2.5 vs v2.5.1 → (2,5,0) < (2,5,1)）。
    """
    s = str(v or "").strip()
    # 尾部必须要么是结尾，要么用 - + 空格 之类分隔符带后缀（v2.5-beta 合法）。
    # 不加这个约束的话 "v2.5garbage" 会被截成 v2.5 接受，脏数据也能触发更新。
    m = re.match(r"^v?(\d+(?:\.\d+)*)(?:[-+ _].*)?$", s)
    if not m:
        return None
    try:
        return tuple(int(x) for x in m.group(1).split("."))
    except ValueError:
        return None


def _ver_gt(a, b):
    """版本号 a > b？逐段比数值，段数不同补 0（(2,5) vs (2,5,1) 视为小于）。"""
    ka, kb = _ver_key(a), _ver_key(b)
    if not ka or not kb:
        return False
    n = max(len(ka), len(kb))
    ka = ka + (0,) * (n - len(ka))
    kb = kb + (0,) * (n - len(kb))
    return ka > kb


def update_check(force=False):
    """拉服务端 version.json 与 APP_VER 比对。成功结果缓存 10 分钟。"""
    now = time.time()
    if not force and _UPDATE_CACHE["info"] and now - _UPDATE_CACHE["t"] < 600:
        return _UPDATE_CACHE["info"]
    info = {"cur": APP_VER, "has_update": False}
    bases = update_bases()
    if not bases:                  # 没有更新源：告诉前端「无在线更新」
        info["offline"] = True
        return info
    try:
        import urllib.request
        op = urllib.request.build_opener(urllib.request.ProxyHandler({}))
        meta = None
        last = None
        for base in bases:         # 依次尝试（jsDelivr → ghproxy → raw）
            try:
                raw = op.open(base + "/version.json", timeout=8).read().decode("utf-8")
                meta = json.loads(raw)
                info["src"] = base
                break
            except Exception as e:                         # noqa: BLE001
                last = e
                continue
        if meta is None:
            raise last or RuntimeError("no update source")
        info.update(meta)
        # ⚠ 必须走 _ver_gt（逐段补 0 比较），不能直接 `nk > ck` 比元组：
        # (2, 5) > (2, 5, 1) 在 Python 里是 False（逐项比到第二项相等后，
        # 短元组更小），可实际 v2.5.1 比 v2.5 新，会把新版本判成「没有更新」。
        info["has_update"] = _ver_gt(meta.get("ver"), APP_VER)
        info.pop("error", None)
        _UPDATE_CACHE.update(t=now, info=info)
    except Exception as e:                                     # noqa: BLE001
        info["error"] = repr(e)
    return info


_UPD_BAT = """@echo off
rem 关键：清掉 PyInstaller 传来的「解压目录」标记。本脚本是旧进程的后代，若不清，
rem 下面 start 起的新 exe 会被 bootloader 当成「旧进程的子进程」而**复用旧进程的解压
rem 目录**：跑的还是旧版代码，而且那份目录在旧进程退出时已被删过一遍（在 x64 机器上
rem win-arm64 / win-x86 的 WebView2Loader.dll 没人占用，会被删掉），新版一启动就报
rem Cannot find win-arm64。清掉后新 exe 作为顶层进程自己解压一份干净的。
set "_PYI_PARENT_PROCESS_LEVEL="
set "_PYI_APPLICATION_HOME_DIR="
set "_MEIPASS="
echo BAT-START %DATE% %TIME% > "%TEMP%\\fys_upd_trace.txt"
set "NEW=%TEMP%\\FYS-Reward.new.exe"
set "BAK=%TEMP%\\FYS-Reward.prev.exe"
set "DST={dst}"
set "WANT={size}"
set "PID={pid}"
set /a N=0
:wait
rem 注意: 只按【本次实例自己的 PID】判断有没有退出。用 /IM FYS-Reward.exe 判断的话，
rem 用户若在别的目录也开着一份同名 exe（本程序允许多开），会被当成「自己还没退出」
rem 而白等，超时后还会被强杀 —— 那个实例本次压根没参与更新。
tasklist /FI "PID eq %PID%" 2>NUL | find /I "%PID%" >NUL
if errorlevel 1 goto backup
set /a N+=1
if %N% GEQ 15 goto force
rem 用 ping 做延时：timeout 在无控制台的隐藏窗口里会报错，导致循环瞬间耗尽
ping -n 2 127.0.0.1 >NUL
goto wait
:force
rem bootloader 父进程有时不跟随子进程退出，等 15 秒后强制收尾（无状态看板，安全）
echo BAT-FORCE >> "%TEMP%\\fys_upd_trace.txt"
taskkill /F /PID %PID% >NUL 2>&1
ping -n 2 127.0.0.1 >NUL
taskkill /F /PID %PID% >NUL 2>&1
:backup
rem 先备份旧 exe：万一新 exe 复制不完整，能回滚，用户不至于「更新完打不开」
copy /y "%DST%" "%BAK%" >NUL 2>&1
rem 注意: 备份必须真的核对出来：备份没做成（磁盘不够 / 被杀软锁住）却继续覆盖的话，
rem 新 exe 一旦有问题就是「新版打不开、旧版也没了」，只能重装。
set "BAKZ="
set "SRCZ="
for %%A in ("%BAK%") do set "BAKZ=%%~zA"
for %%A in ("%DST%") do set "SRCZ=%%~zA"
echo BAT-BAK %BAKZ%/%SRCZ% >> "%TEMP%\\fys_upd_trace.txt"
if "%BAKZ%"=="" goto abort
if not "%BAKZ%"=="%SRCZ%" goto abort
echo BAT-COPY >> "%TEMP%\\fys_upd_trace.txt"
copy /y "%NEW%" "%DST%" >NUL 2>&1
if not errorlevel 1 goto verify
ping -n 3 127.0.0.1 >NUL
taskkill /F /PID %PID% >NUL 2>&1
ping -n 2 127.0.0.1 >NUL
copy /y "%NEW%" "%DST%" >NUL 2>&1
if not errorlevel 1 goto verify
ping -n 3 127.0.0.1 >NUL
copy /y "%NEW%" "%DST%" >NUL 2>&1
if not errorlevel 1 goto verify
goto rollback
:verify
rem 复制完核对字节数：杀软 hook 写盘可能造成截断/半写，半截 exe 启动会弹
rem 「Failed to load Python DLL」这种看不懂的错，不如当场发现重来
for %%A in ("%DST%") do set "GOT=%%~zA"
echo BAT-SIZE %GOT%/%WANT% >> "%TEMP%\\fys_upd_trace.txt"
if "%GOT%"=="%WANT%" goto ok
ping -n 3 127.0.0.1 >NUL
taskkill /F /PID %PID% >NUL 2>&1
copy /y "%NEW%" "%DST%" >NUL 2>&1
for %%A in ("%DST%") do set "GOT=%%~zA"
if "%GOT%"=="%WANT%" goto ok
goto rollback
:rollback
rem 新 exe 校验不过：回滚旧版并照常启动，功能回到更新前（本次更新失败可重试）
echo BAT-ROLLBACK >> "%TEMP%\\fys_upd_trace.txt"
copy /y "%BAK%" "%DST%" >NUL 2>&1
rem 注意: 回滚也要确认真的拷回去了：拷失败却照样删备份，等于把最后一份好的弄丢
set "RBZ="
for %%A in ("%DST%") do set "RBZ=%%~zA"
if "%RBZ%"=="%BAKZ%" (
  del "%NEW%" >NUL 2>&1
  del "%BAK%" >NUL 2>&1
)
cd /d "{dir}"
start "" "%DST%"
del "%~f0"
exit /b 1
:abort
rem 备份做不出来：宁可这次不更新，也不能让用户「更新完打不开」
echo BAT-ABORT >> "%TEMP%\\fys_upd_trace.txt"
del "%NEW%" >NUL 2>&1
cd /d "{dir}"
start "" "%DST%"
del "%~f0"
exit /b 1
:ok
del "%DST%.lk" 2>NUL
rem 启动前自适应缓冲：杀软对新写盘的 exe 有 1~? 秒扫描锁，锁没放就启动会弹
rem 「Failed to load Python DLL」。这里用「独占改名」探测文件是否已被释放——
rem 占用的话 move 失败就等，释放了立刻移回原样，绝不损坏 exe（有复制兜底）。
rem 注意: ping -n N 只等 N-1 秒（发 N 个包、间隔 1 秒）。每轮 -n 3 = 2 秒，
rem 40 轮上限 ≈ 80 秒（够慢的杀软扫完）。v2.5 只给了 12 轮≈12 秒，杀软扫得慢
rem 的机器照样会撞 DLL 报错（2026-09-28 加固；另见下方说明：老版本的自更新器
rem 没有这段缓冲，旧版升新版若撞 DLL，只能手动覆盖一次 exe 越过）。
set /a _lk=0
:lockwait
set /a _lk+=1
move "%DST%" "%DST%.lk" >NUL 2>NUL
if errorlevel 1 (
  if %_lk% GEQ 40 goto launch
  ping -n 3 127.0.0.1 >NUL
  goto lockwait
)
move "%DST%.lk" "%DST%" >NUL 2>NUL
if errorlevel 1 (
  copy /y "%DST%.lk" "%DST%" >NUL 2>NUL
  del "%DST%.lk" >NUL 2>NUL
)
:launch
rem 锁已释放，再给系统 3 秒收尾（让杀软彻底松手），然后启动
ping -n 4 127.0.0.1 >NUL
cd /d "{dir}"
start "" "%DST%"
rem 注意: 必须【先启动、再清理】：反过来先删备份的话，万一 start 没起来，
rem 用户就既没有新版也没有能回滚的旧版，只能重新下载安装包。
ping -n 2 127.0.0.1 >NUL
del "%NEW%" >NUL 2>&1
del "%BAK%" >NUL 2>&1
echo BAT-DONE >> "%TEMP%\\fys_upd_trace.txt"
del "%~f0"
"""


def update_apply():
    """流式下载新版 exe（带进度/失败重试）→ sha256 强校验 → 写自替换 bat → 退出，
    由 bat 换文件并重启。version.json 缺 sha256 一律拒绝更新（防塞错/被篡改）。"""
    if not getattr(sys, "frozen", False):
        return {"ok": False, "error": "开发模式不支持就地更新"}
    meta = update_check(force=True)
    if meta.get("error"):
        return {"ok": False, "error": "取版本信息失败: " + meta["error"]}
    # 离线版（v2.14 起不再依赖服务器）：没有更新源，报清楚「去下新版压缩包」，
    # 别让用户看到「缺少校验值」这种像是服务器出问题的措辞。
    if meta.get("offline"):
        return {"ok": False,
                "error": "当前为离线版（不连接更新服务器），请下载新版压缩包解压覆盖"}
    import hashlib
    import tempfile
    import urllib.request
    # 服务端若把版本撤回成不比本地新的号（或填错），不该还照装——那会把用户
    # 从新版打回旧版，还可能因为重装同版本白重启一次。
    if meta.get("ver") and not meta.get("has_update"):
        return {"ok": False,
                "error": "服务端版本 %s 不比当前 %s 新，已取消更新"
                         % (meta.get("ver"), APP_VER)}
    want = str(meta.get("sha256") or "").lower()
    if not want:
        # 安全策略：服务端没给校验值就不做任何替换，宁可更不了也不能盲替
        return {"ok": False, "error": "服务端版本信息缺少校验值，已拒绝更新"}
    dst_dir = os.path.dirname(os.path.abspath(sys.executable))
    dst = os.path.join(dst_dir, "FYS-Reward.exe")
    tmp = os.path.join(tempfile.gettempdir(), "FYS-Reward.new.exe")

    # 下载地址：优先 version.json 里的 urls（通常是 GitHub Release 资产，
    # 带 ghproxy 镜像一起给，国内直连 releases 容易超时）；没有就退回
    # 「清单地址 + 文件名」，兼容老的静态目录布局。
    _urls = meta.get("urls") or []
    if isinstance(_urls, str):
        _urls = [_urls]
    if not _urls:
        _name = meta.get("file") or "FYS-Reward.exe"
        _urls = [b + "/" + _name for b in (bases or update_bases())]

    def _download(url):
        """按 1MB 块流式写盘并滚动算哈希；进度写 _UPD_PROG 供前端轮询。"""
        op = urllib.request.build_opener(urllib.request.ProxyHandler({}))
        with op.open(url, timeout=60) as r:
            total = int(r.headers.get("Content-Length") or 0)
            _UPD_PROG.update(phase="download", got=0, total=total)
            h = hashlib.sha256()
            with open(tmp, "wb") as f:
                while True:
                    blk = r.read(1 << 20)
                    if not blk:
                        break
                    f.write(blk)
                    h.update(blk)
                    _UPD_PROG["got"] += len(blk)
        return h.hexdigest()

    try:
        digest, err = None, None
        # 每个地址最多试 2 次（瞬时断网），一个地址不行就换下一个镜像
        for url in _urls:
            for attempt in (1, 2):
                try:
                    digest = _download(url)
                    err = None
                    break
                except Exception as e:             # noqa: BLE001
                    err = e
                    _UPD_PROG["phase"] = "retry" if attempt == 1 else "error"
                    log("update: 下载失败（%s 第 %d 次）%r" % (url[:80], attempt, e))
                    time.sleep(0.8)
            if err is None:
                break
        if err is not None:
            raise err
        _UPD_PROG["phase"] = "verify"
        if digest != want:
            _UPD_PROG["phase"] = "error"
            try:
                os.remove(tmp)
            except OSError:
                pass
            return {"ok": False, "error": "下载校验不符，已取消更新"}
        _UPD_PROG["phase"] = "install"
        # 替换 exe 前先让屏幕覆盖小窗退出：它是本进程的子进程，占着本次运行的解压
        # 目录；不放它走的话，本进程退出时 bootloader 删目录只能删掉一半（留下残缺
        # 目录），一旦被下一版复用就是「更新后打不开」（v2.6→v2.7 的真实事故）。
        try:
            if ov_alive():
                ov_close()
                for _ in range(20):                    # 最多等 4 秒
                    if not ov_alive():
                        break
                    time.sleep(0.2)
                log("update: 覆盖小窗已退出" if not ov_alive()
                    else "update: 覆盖小窗未及时退出，继续更新")
        except Exception as e:                         # noqa: BLE001
            log("update: 关闭覆盖小窗失败（忽略）%r" % (e,))
        bat = os.path.join(dst_dir, "_update.bat")
        # ⚠ 路径里的 % 必须写成 %%：CMD 会把 %xxx% 当变量展开，装在一个
        # 名字带 % 的目录（如 C:\100%real\）下时，DST 会被展开成错的，
        # 于是脚本找不到目标文件、更新后起不来（Python 侧已经返回 ok 了）。
        # 只转义传进去的路径，BAT 模板自带的 %TEMP% / %PID% 要原样保留。
        bat_text = _UPD_BAT.format(dst=dst.replace("%", "%%"),
                                   dir=dst_dir.replace("%", "%%"),
                                   pid=os.getpid(),
                                   size=os.path.getsize(tmp))
        try:
            bat_text.encode("gbk")                 # 路径能用 GBK 表示就走老编码（兼容现状）
            enc = "gbk"
        except UnicodeEncodeError:
            # exe 所在目录含 GBK 外字符（生僻字/emoji）时，GBK 会把路径写成「?」
            # 导致自替换静默失败——改写 UTF-8 bat，开头 chcp 65001 让 cmd 按 UTF-8 解析
            bat_text = bat_text.replace("@echo off", "@echo off\r\nchcp 65001 >NUL", 1)
            enc = "utf-8"
        with open(bat, "w", encoding=enc, newline="\r\n") as f:
            f.write(bat_text)
        # 隐藏窗口 + 完全脱离本进程：程序退出后它继续完成替换与重启。
        # 必须显式走 cmd.exe（CreateProcess 不直接执行 .bat），且用
        # CREATE_NO_WINDOW 而非 DETACHED_PROCESS —— 无控制台时 cmd 跑批处理会
        # 静默失败（实测：进程都没起来，bat 原样留在原地）。
        log("update: spawn bat -> %s" % bat)
        try:
            subprocess.Popen([os.environ.get("ComSpec", "cmd.exe"), "/c", bat],
                             creationflags=0x08000000,           # CREATE_NO_WINDOW
                             stdin=subprocess.DEVNULL,
                             stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL)
            log("update: Popen 返回（进程已创建）")
        except Exception as e:                                 # noqa: BLE001
            log("update: Popen 异常 %r" % (e,))
            raise
        threading.Timer(1.5, os._exit, (0,)).start()
        return {"ok": True}
    except Exception as e:                                     # noqa: BLE001
        try:
            os.remove(tmp)
        except OSError:
            pass
        return {"ok": False, "error": repr(e)}


def _livetxt_text(d):
    """按覆盖窗「显示内容」开关生成纯文本（与屏幕覆盖小窗同源）。"""
    cfg = ensure_ovcfg()
    show = cfg.get("show") or {}
    c = d.get("current") or {}
    import mapnames

    def wan(v):
        """伤害/分数统一按「万」：≥1000 才换算，1 位小数（与页面 wan() 同规则）。"""
        if v is None:
            return "—"
        try:
            v = float(v)
        except (TypeError, ValueError):
            return str(v)
        if v < 1000:
            return "%g" % v
        # floor(x+0.5) 而不是 Python 内置 round：内置是银行家舍入，2500 会算成 0.2w，
        # 与页面 JS 的 Math.round（0.3w）对不上，覆盖窗和主界面会显示不同数字
        x = math.floor(v / 10000 * 10 + 0.5) / 10
        return ("%g" % x) + "w"

    def g(k, default="—"):
        v = c.get(k)
        return default if v is None else v

    pairs = [
        ("map",     "地图",     d.get("map") or "—"),
        ("mapcn",   "译名",     d.get("mapcn") or mapnames.cn(d.get("map") or "") or "—"),
        ("stage",   "关卡",
         ("第 %s / %s 关" % (d.get("stage"), d.get("total_stages") or "?"))
         if d.get("stage") else "—"),
        ("passes",  "通关云点", g("rankPasses")),
        ("dmgrank", "伤害云点", wan(c.get("rankDamage"))),
        ("econ",    "通关龙晶", g("econPasses")),
        ("dmgecon", "伤害龙晶", wan(c.get("econDamage"))),
    ]
    if not d.get("map"):
        # 未进服 / 查询中：只写一行状态，别让 OBS 里挂着一整列「—」（与覆盖小窗一致）
        return d.get("state_text") or "未进入服务器"
    lines = ["%s：%s" % (lab, v) for k, lab, v in pairs if show.get(k, True)]
    if not lines:
        return ""
    return "\n".join(lines)


_LIVETXT_LOCK = threading.Lock()
_LIVETXT_ERR = {"t": 0.0}   # 上次异常上报时间（限频：60 秒最多记一条，别刷爆日志）


def livetxt_tick(d):
    """主窗口每秒轮询 /api/status 时顺手刷新直播文本；内容没变不写盘。

    两个输出目标（自己的 txt / fys 直播助手同款路径）内容一致，
    各自记一份上次写入的签名，谁没变化就不碰谁。

    坑（都踩过）：
      · 签名必须在**写盘成功之后**才记 —— OBS「文本(GDI+)」占用着文件时
        os.replace 会抛 WinError 32，先记签名会导致后续永远判定「没变化」，
        txt 停在旧内容不动。
      · /api/status 会被主窗口和覆盖子进程并发调用，两个线程共用同一个
        `<p>.tmp` 会互相搬走半截文件 → 临时名带上线程 id。
    """
    try:
        targets = livetxt_targets(ensure_ovcfg())
        if not targets:
            return
        text = _livetxt_text(d)
        with _LIVETXT_LOCK:
            for key, p in targets:
                if text == _LIVETXT_LAST.get(key):
                    continue
                if key == "live" and os.path.exists(p) and not os.path.exists(p + ".bak"):
                    try:               # 首次覆盖官方文件前先留个备份，防手抖丢数据
                        import shutil
                        shutil.copy2(p, p + ".bak")
                    except OSError as e:
                        # 不能静默：备份失败还继续覆盖 = 官方原文件丢失无退路
                        log("[直播文本] 备份失败仍继续写入 %s：%r" % (p, e))
                os.makedirs(os.path.dirname(p), exist_ok=True)
                tmp = "%s.%d.tmp" % (p, threading.get_ident())
                try:
                    with open(tmp, "w", encoding="utf-8-sig") as fh:
                        fh.write(text)
                    os.replace(tmp, p)
                except OSError as e:
                    log("[直播文本] 写入失败 %s：%r" % (p, e))
                    try:
                        os.remove(tmp)
                    except OSError:
                        pass
                    continue
                _LIVETXT_LAST[key] = text
    except Exception as e:                                     # noqa: BLE001
        # 原来这里裸 except pass，任何 bug（含拼写错/导入失败）都被静默吞掉，
        # txt 停更无从排查。限频记日志：60 秒最多一条，异常持续也不刷屏。
        now = time.time()
        if now - _LIVETXT_ERR["t"] > 60:
            _LIVETXT_ERR["t"] = now
            log("[直播文本] 处理异常（60 秒内只记这一次）：%r" % (e,))


def livetxt_remove(which=None):
    """清掉直播文本（避免 OBS / 直播助手读到旧数据）。

    which=None 清全部；which='own'/'live' 只清单个（某个开关关掉时用）。
    """
    for key, p in (("own", livetxt_path()),):
        if which and key != which:
            continue
        _LIVETXT_LAST.pop(key, None)
        try:
            os.remove(p)
        except OSError:
            pass


def ov_alive():
    p = State.ovproc
    return p is not None and p.poll() is None


# ── 覆盖窗落点：四角预设（拖动过的精确坐标优先，预设只决定「首次落点」） ──
OV_POS_MARGIN = 40          # 离屏幕边缘留白


def ov_preset_xy(pos):
    """按预设角落算覆盖窗初始坐标 -> (x, y)。

    窗口尺寸取最近一次报上来的尺寸（内容撑高后），拿不到就按 420x220 估。
    """
    w, h = State.ovsize or (420, 220)
    try:
        import ctypes
        u = ctypes.windll.user32
        try:
            u.SetProcessDPIAware()
        except Exception:                                      # noqa: BLE001
            pass
        sw, sh = int(u.GetSystemMetrics(0)), int(u.GetSystemMetrics(1))
    except Exception:                                          # noqa: BLE001
        sw, sh = 1920, 1080
    m = OV_POS_MARGIN
    x = m if pos in ("lt", "lb") else max(m, sw - w - m)
    y = m if pos in ("lt", "rt") else max(m, sh - h - m)
    return int(x), int(y)


def ov_start_xy(cfg=None):
    """启动覆盖窗时的初始坐标：精确坐标 > 预设角落 > 左上角兜底。"""
    cfg = cfg if cfg is not None else ensure_ovcfg()
    try:
        if isinstance(cfg.get("x"), int) and isinstance(cfg.get("y"), int):
            return int(cfg["x"]), int(cfg["y"])
    except Exception:                                          # noqa: BLE001
        pass
    pos = cfg.get("ov_pos") or "rt"
    if pos not in ("lt", "rt", "lb", "rb"):
        pos = "rt"
    return ov_preset_xy(pos)


_OV_LOCK = threading.Lock()


def ov_open(force=False):
    """用独立子进程启动屏幕覆盖小窗。
    透明窗口只有在「窗口是该进程第一个主窗口」时才可靠生效；
    在主进程消息循环中动态 create_window 会让 WebView2 白底露出来（白边问题）。
    mode=tkinter 时改用原生分层窗（PIL 渲染，文字无描边、透明最彻底）。
    force=True：不管旧覆盖进程是否还在退出中都拉起新窗（重启提速用——
    旧窗的窗口已销毁、只剩进程拆卸，视觉上无重叠，没必要干等它退干净）。"""
    if not force:
        if ov_alive():
            return {"ok": True, "on": True}
    with _OV_LOCK:                     # 锁内复查：连点两次/并发请求只会拉起一个子进程
        if not force and ov_alive():
            return {"ok": True, "on": True}
        State.ovproc = None
        State.ovclose_flag = False
        State.ov_user_close = False
        mode = (ensure_ovcfg().get("mode") or "frameless")
        flag = "--overlay-tk" if mode == "tkinter" else "--overlay"
        exe = sys.executable
        if getattr(sys, "frozen", False):
            cmd = [exe, flag, "--url", State.url]
        else:
            cmd = [exe, os.path.abspath(__file__), flag, "--url", State.url]
        try:
            State.ovproc = subprocess.Popen(cmd, cwd=BASE_DIR,
                                            creationflags=_NO_WINDOW)
        except Exception as e:                                     # noqa: BLE001
            return {"ok": False, "error": repr(e)}
    return {"ok": True, "on": True}


def _ov_save_pos(win):
    """覆盖窗关闭前把位置写回 overlay.json，下次原地打开。

    只回存 x/y，且以磁盘上的最新配置为基底合并——子进程缓存里的其他键
    （ov_ct/mode/color…）可能是它启动时的旧值：切穿透/换模式触发重启时，
    主程序已把新配置落盘，旧窗此时才退出，整份回存会把新配置整体盖掉
    （实测症状：勾上穿透后新窗仍无穿透、且位置回到默认）。
    """
    try:
        with open(_ovcfg_path(), encoding="utf-8") as fh:
            cfg = json.load(fh)
        if not isinstance(cfg, dict):
            return
        cfg["x"], cfg["y"] = int(win.x), int(win.y)
        save_ovcfg(cfg)
        log("overlay child: 回存位置 x=%s y=%s" % (cfg["x"], cfg["y"]))
    except Exception:                                          # noqa: BLE001
        log("overlay child: 回存位置失败:\n" + traceback.format_exc())


def ov_shutdown_on_exit():
    """主窗口关闭后让覆盖小窗立刻跟着退（正常关闭路径零屏幕残留）。

    以前靠小窗自己探活失败自愈，实测要 ~30 秒屏幕残留；现在位置由小窗的
    拖动检测随时落盘，这里走 close 指令让它走正常收尾（顺带最后一次精确
    回存），3 秒内没退才整树强杀兜底。崩溃/被任务管理器杀掉主程序时，
    小窗仍走自愈路径（自毁前也会回存位置）。
    """
    p = State.ovproc
    if p is None or p.poll() is not None:
        State.ovproc = None
        return
    State.ovclose_flag = True
    State.ov_nosave = False
    deadline = time.time() + 3.0
    while time.time() < deadline and p.poll() is None:
        time.sleep(0.1)
    if p.poll() is None:
        try:
            subprocess.run(["taskkill", "/F", "/T", "/PID", str(p.pid)],
                           capture_output=True, timeout=6,
                           creationflags=_NO_WINDOW)
        except Exception:                                      # noqa: BLE001
            pass


def ov_close():
    if not ov_alive():
        State.ovproc = None
        return {"ok": True, "on": False}
    p = State.ovproc
    State.ovclose_flag = True          # 覆盖进程轮询 /api/ovpoll 自行退出
    State.ov_user_close = True         # 记下「这是用户/外部主动关」：重启流程会先清掉它
    def _kill():
        time.sleep(3.0)                # 兜底：3 秒还没退就强杀
        if p.poll() is None and State.ovproc is p:
            try:
                p.terminate()
            except Exception:                                  # noqa: BLE001
                pass
    threading.Thread(target=_kill, daemon=True).start()
    return {"ok": True, "on": False}


def _ov_restore_focus(prev):
    """换布局重建小窗后，若覆盖窗抢走了焦点，把焦点还给「重建前的前台窗口」
    （可能是游戏，也可能是主程序）。只有焦点确实被覆盖窗进程抢走时才归还，
    绝不主动把焦点从主程序推给游戏。用 AttachThreadInput 绕过 Windows 前台锁，
    否则跨进程 SetForegroundWindow 会被静默忽略。"""
    if not prev:
        return
    try:
        import ctypes
        u = ctypes.windll.user32
        if not u.IsWindow(prev):
            return
        cur = u.GetForegroundWindow()
        if not cur or cur == prev:
            return
        # 焦点是否落在覆盖窗进程上？不是就不动（避免误伤）
        if State.ovproc is not None:
            _pid = ctypes.c_ulong()
            u.GetWindowThreadProcessId(cur, ctypes.byref(_pid))
            try:
                _cur_pid = State.ovproc.pid
            except Exception:                          # noqa: BLE001
                _cur_pid = None
            if _cur_pid is not None and int(_pid.value) != int(_cur_pid):
                return
        _fg = ctypes.c_ulong()
        u.GetWindowThreadProcessId(cur, ctypes.byref(_fg))
        _tgt = ctypes.c_ulong()
        u.GetWindowThreadProcessId(prev, ctypes.byref(_tgt))
        _attached = False
        if _fg.value and _fg.value != _tgt.value:
            u.AttachThreadInput(_fg.value, _tgt.value, True)
            _attached = True
        try:
            u.SetForegroundWindow(prev)
            u.SetActiveWindow(prev)
        finally:
            if _attached:
                u.AttachThreadInput(_fg.value, _tgt.value, False)
    except Exception:                                  # noqa: BLE001
        pass


def _ov_focus_guard(prev, stop):
    """换布局/换模式/清底图重建小窗后，把「WebView2 滞后激活」抢走的那一次焦点
    还给「重建前的前台窗口」（游戏/主程序）。

    ⚠ 2026-09-29 修「切换布局仍把游戏弹到后台」：旧逻辑只在重建后做一次
    `_ov_restore_focus`，但 WebView2 的首帧导航 / 渲染进程 / GPU 进程重建可能
    **滞后**才把窗口激活到前台（和「穿透用久了失效」同源：子窗后建）。单次还原
    往往跑在 WebView2 真正激活之前，于是小窗随后又抢回前台、游戏被弹到后台。
    这里照穿透守护线程的思路：新窗起来后 3.5 秒内每 0.15s 复查一次。

    ⚠ 2026-09-29 二次修正：改成**只还原首次窃取**——一旦检测到覆盖进程抢了焦点
    就还原一次并立即退出。原因：若整段 3.5s 都持续夺回，用户在这窗口内主动点
    覆盖窗去拖动（未开穿透时）会被判成「覆盖进程抢焦点」而把焦点夺回游戏，导致
    小窗一时拖不动。首帧导航带来的激活基本只发生一次，还原一次足够；
    `_ov_restore_focus` 自带进程判定，别的窗口在前台时不动，绝不误抢。"""
    if not prev:
        return
    import ctypes
    u = ctypes.windll.user32
    deadline = time.time() + 3.5
    while time.time() < deadline and not stop.is_set():
        time.sleep(0.15)
        if stop.is_set():
            return
        try:
            if not u.IsWindow(prev):
                return
            cur = u.GetForegroundWindow()
            if not cur or cur == prev:
                continue
            # 只处理「覆盖进程抢了焦点」的情况；别的窗口在前台就不抢（避免误伤）。
            # 覆盖子进程不在（None/已退出）时不还原，避免把 prev 强行抢回前台。
            if State.ovproc is None:
                continue
            _pid = ctypes.c_ulong()
            u.GetWindowThreadProcessId(cur, ctypes.byref(_pid))
            try:
                _cur_pid = State.ovproc.pid
            except Exception:                              # noqa: BLE001
                _cur_pid = None
            if _cur_pid is None or int(_pid.value) != int(_cur_pid):
                continue
            _ov_restore_focus(prev)
            return                                         # 只还原首次就收工
        except Exception:                              # noqa: BLE001
            pass


def ov_restart(nosave=False, structural_changed=False):
    """切换渲染模式 / 换预设落点用：先关掉当前覆盖窗，等它退出后按新配置重开。

    nosave=True 时临时屏蔽「关闭时回存位置」——否则旧窗口退出时会把刚清掉的
    坐标又写回去，预设落点永远不生效。
    """
    def _run():
        try:                                    # 记下来重建前谁在前台（游戏/主程序），
            import ctypes as _ct                 # 重建后若覆盖窗抢了焦点就还回去
            _prev_fg = _ct.windll.user32.GetForegroundWindow()
        except Exception:                       # noqa: BLE001
            _prev_fg = None
        State.ov_nosave = bool(nosave)
        ov_close()
        # 重启流程自己触发的关闭不算「用户要关」——否则下面这条守卫永远命中，
        # ov_restart 就永远不再拉起新窗（模式切换/预设落点/穿透开关全失效）
        State.ov_user_close = False
        # 给旧窗 ~0.8s 自己收尾（轮询到 close → 回存位置 → 开始销毁窗口），
        # 还没退干净就直接终止进程树：实测 win.destroy 之后 WebView2 的进程
        # 拆卸能拖 4s+，干等它就是用户看到的「切换后好几秒才刷新出来」。
        # 位置回存在销毁前就已落盘（save_ovcfg 原子写），终止不会截断配置。
        deadline = time.time() + 0.8
        while time.time() < deadline and ov_alive():
            time.sleep(0.1)
        p0 = State.ovproc
        if p0 is not None and p0.poll() is None:
            try:
                subprocess.run(["taskkill", "/F", "/T", "/PID", str(p0.pid)],
                               capture_output=True, timeout=10,
                               creationflags=_NO_WINDOW)
            except Exception:                                  # noqa: BLE001
                try:
                    p0.terminate()
                except Exception:                              # noqa: BLE001
                    pass
        for _ in range(10):
            if not ov_alive():
                break
            time.sleep(0.1)
        if State.ov_user_close:        # 等待期间用户点了「关闭覆盖」→ 不许再弹回来
            State.ov_nosave = False
            return
        time.sleep(0.1)            # 子进程退出前已同步回存 overlay.json，留个刷盘余量即可
        ov_open(force=True)
        # 等新覆盖窗真正起来（最多 6 秒）再恢复「关闭时回存」：
        # 原来固定 sleep 2.5s，慢机器上新窗还没起来就清标志，旧回存路径可能竞态写回
        for _ in range(30):
            if ov_alive():
                break
            time.sleep(0.2)
        time.sleep(0.5)
        State.ov_nosave = False
        # Bug G（2026-09-29）：单次还焦点不够（WebView2 滞后激活会再抢），
        # 改为窗口期内反复夺回（见 _ov_focus_guard）。先停掉上一次可能还在跑的守护。
        try:
            if getattr(State, "_ov_fg_stop", None) is not None:
                State._ov_fg_stop.set()
        except Exception:                                  # noqa: BLE001
            pass
        if _prev_fg:
            _fg_stop = threading.Event()
            State._ov_fg_stop = _fg_stop
            threading.Thread(target=_ov_focus_guard,
                             args=(_prev_fg, _fg_stop), daemon=True).start()
    threading.Thread(target=_run, daemon=True).start()
    return {"ok": True}


# ── 地图实体预览窗口（2026-09-24 用户拍板：从系统浏览器改回软件内打开）──
# 独立 pywebview 子进程（同覆盖窗模式）：不嵌 iframe，WebGL 渲染与主界面互不拖卡；
# 有系统标题栏，可最大化 / 拖到第二块屏。
PV_TITLE = "地图实体预览"


def pv_alive():
    p = State.pvproc
    return p is not None and p.poll() is None


def pv_focus():
    """预览窗已开着时把它切到前台（按窗口标题找）。"""
    try:
        import ctypes
        h = ctypes.windll.user32.FindWindowW(None, PV_TITLE)
        if h:
            ctypes.windll.user32.SetForegroundWindow(h)
            return True
    except Exception:                                          # noqa: BLE001
        pass
    return False


def pv_kill():
    """onefile 打包后是「bootloader 父进程 + 应用子进程」，收尾必须整树杀。"""
    p = State.pvproc
    State.pvproc = None
    if p is None or p.poll() is not None:
        return
    try:
        if os.name == "nt":
            subprocess.run(["taskkill", "/F", "/T", "/PID", str(p.pid)],
                           capture_output=True, timeout=6,
                           creationflags=_NO_WINDOW)
        else:
            p.terminate()
    except Exception:                                          # noqa: BLE001
        pass


def pv_open(map_name=""):
    """在软件内打开地图实体预览：独立子进程 pywebview 窗口。
    已开着且同一张图 → 只切前台；换了图 → 关旧开新。"""
    base = (State.url or "").split("?")[0]
    if not base:
        base = "http://127.0.0.1:%d/" % (State.port or 80)
    map_name = (map_name or "").strip()
    if pv_alive():
        if State.pvmap == map_name and pv_focus():
            return {"ok": True, "reused": True}
        pv_kill()                    # 换图：旧窗关掉再开新的（预览页 ?map= 不会热切）
    th = load_uiprefs().get("theme") or "E"           # 预览窗跟随软件主题
    if th not in ("E", "F", "G", "H", "N"):
        th = "E"
    u = base + "preview3d?" + (("map=" + urllib.parse.quote(map_name) + "&") if map_name else "") + "th=" + th
    exe = sys.executable
    if getattr(sys, "frozen", False):
        cmd = [exe, "--preview", "--url", u]
    else:
        cmd = [exe, os.path.abspath(__file__), "--preview", "--url", u]
    try:
        State.pvproc = subprocess.Popen(cmd, cwd=BASE_DIR,     # noqa: S606
                                        creationflags=_NO_WINDOW)
        State.pvmap = map_name
    except Exception as e:                                     # noqa: BLE001
        return {"ok": False, "error": repr(e)}
    return {"ok": True, "url": u}


def _pv_poller(win, base):
    """主程序退出后预览窗跟着退（同覆盖窗思路，改成纯探活）。"""
    import urllib.request
    # 必须绕开系统代理：127.0.0.1 被代理拦时会误判主程序已死（_tk_http 同款处理）
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    fails = 0
    while True:
        time.sleep(4)
        try:
            opener.open(base.rstrip("/") + "/api/prefs", timeout=3).read()  # noqa: S310
            fails = 0
        except Exception:                                      # noqa: BLE001
            fails += 1
            if fails > 3:
                try:
                    win.destroy()
                except Exception:                              # noqa: BLE001
                    pass
                return


def run_preview_child():
    """--preview 子进程入口：地图实体预览独立窗口（有系统标题栏）。"""
    args = sys.argv[1:]
    url = ""
    if "--url" in args:
        url = args[args.index("--url") + 1]
    if not url:
        return
    import webview
    log("preview child: 准备创建预览窗口 url=%s" % url)
    win = webview.create_window(
        PV_TITLE, url,
        width=1280, height=820, min_size=(640, 420),
        resizable=True,
        background_color="#211c2b",   # 深色打底，避免加载瞬间白闪
    )
    # 探活只用「协议://主机:端口」——带 /preview3d 路径会拼出 404 地址，
    # 连续失败后预览窗几秒就自己关了（2026-09-24 用户实测踩坑）
    sp = urllib.parse.urlsplit(url)
    origin = "%s://%s" % (sp.scheme, sp.netloc)
    threading.Thread(target=_pv_poller, args=(win, origin),
                     daemon=True).start()
    webview.start()
    log("preview child: 消息循环退出")


# ── 覆盖子进程入口（--overlay）：此进程里覆盖窗是第一个主窗口，透明才生效 ──
# 注意：绝不走 pywebview 的 JS 桥（api.resize 回调会在后台线程做同步 Invoke /
# SetWindowPos，实测会把覆盖窗 GUI 线程卡成"未响应"）。
# 尺寸调整与关闭全部走 HTTP 轮询：JS fetch 主程序 -> 主程序记录 -> 本进程 Python
# 轮询 /api/ovpoll 拿到目标尺寸/关闭指令后，在自己线程里安全地操作窗口。
def _ov_poller(win, base):
    import urllib.request
    # 必须绕开系统代理：用户开了代理且没排除 127.0.0.1 时，urlopen 会走代理 →
    # 连续超时 8 次后覆盖窗会「自己消失」，看起来像主程序崩了（_tk_http 同款处理）
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    last = None
    fails = 0
    cur = None                   # 上一轮窗口位置（拖动检测用）
    saved = None                 # 已落盘的位置
    moved_at = 0.0               # 位置最后一次变化的时刻
    while True:
        try:
            with opener.open(base.rstrip("/") + "/api/ovpoll", timeout=3) as r:
                d = json.load(r)
            fails = 0
        except Exception:                                      # noqa: BLE001
            fails += 1                 # 主程序不在了 -> 自动退出
            if fails > 12:             # 12×0.5≈6s（同旧版容忍度）：启动瞬间主程序忙
                log("overlay child: 自毁流程开始（先回存位置）")
                # 自毁前回存位置：用户关软件（而不是先关覆盖窗）时，这是唯一
                # 能把拖动后坐标写回 overlay.json 的机会——否则下次启动永远
                # 回到预设角落（2026-11-04 玩家反馈「重启就回原位」实证修复）。
                try:                   # 只回存 x/y，主程序死活都不影响落盘
                    _ov_save_pos(win)
                except Exception:                              # noqa: BLE001
                    pass
                try:                   # 不算「不在了」，误判会让覆盖窗开机自毁
                    win.destroy()
                except Exception:                              # noqa: BLE001
                    pass
                return
            time.sleep(0.5)
            continue
        # 鼠标穿透热切换：主程序把磁盘上的 ov_ct 跟着 poll 下发，变了就地改样式
        try:
            _set_clickthrough(bool(d.get("ct")))
        except Exception:                 # noqa: BLE001
            pass
        if d.get("close"):
            if not d.get("nosave"):        # 换预设落点导致的重启：不要回存旧坐标
                _ov_save_pos(win)
            try:
                win.destroy()
            except Exception:                                  # noqa: BLE001
                pass
            # 兜底强制退出（原来 2s：模式切换/穿透开关要等旧进程真正退出才能开新窗，
            # 拖满 2s 用户就会觉得「好几秒才刷新出来」，压到 0.8s——正常路径
            # webview 循环随 destroy 自然结束，这个 Timer 只兜进程卡住的情况）
            threading.Timer(0.8, lambda: os._exit(0)).start()
            return
        try:
            w, h = int(d.get("w") or 0), int(d.get("h") or 0)
        except (TypeError, ValueError):
            w = h = 0
        if w > 0 and h > 0 and (w, h) != last:
            last = (w, h)
            try:
                win.resize(max(120, w), max(48, h))
            except Exception:                                  # noqa: BLE001
                pass
        # 拖动落盘（2026-11-04 玩家反馈「重启就回原位」）：位置稳定 ~1s 即写回
        # overlay.json，不再依赖「关闭那一刻」才存——主程序退出时才能立即
        # 收掉小窗（ov_shutdown_on_exit），屏幕零残留。win.x/y 是实时属性。
        try:
            px, py = int(win.x), int(win.y)
        except Exception:                                      # noqa: BLE001
            px = py = None
        if px is not None:
            if (px, py) != cur:        # 在动：刷新「最后移动时刻」
                cur = (px, py)
                moved_at = time.time()
            elif (px, py) != saved and time.time() - moved_at >= 1.0:
                _ov_save_pos(win)      # 拖停 1 秒 → 落盘一次
                saved = (px, py)
        time.sleep(0.3)     # 0.8→0.3：关闭指令要等下一轮轮询才被看到，太慢会拖重启


# ── 鼠标穿透热切换（v2.3 优化 7）：只改整窗树的 WS_EX_TRANSPARENT，不重建窗口 ──
# 原来切一次穿透 = 关窗 + 重开（小窗闪一下、正在录的画面断一帧）。
# 现在主程序把磁盘上的 ov_ct 跟着 /api/ovpoll 下发给覆盖子进程，子进程发现变了
# 就地改样式：开=整树挂 WS_EX_TRANSPARENT（含晚创建的 WebView2 子窗），关=按快照还原。
#
# ⚠ 2026-09-28 修正「取消穿透后文字消失 / tkinter 拖不动」两处 bug ——
#   旧实现「开 = ex|TR|LAYERED，关 = ex & ~TR」有两个致命假设错误：
#   ① pywebview 的无边框透明窗**本来没有 WS_EX_LAYERED**（它靠 DWM accent 透明，
#      不是分层窗）。旧「开」顺手挂上 LAYERED，「关」却只摘 TR → LAYERED 残留，
#      整窗变成「无属性的分层窗」= 全透明 → 卡片与文字凭空消失（截图实证阶段 C）。
#   ② WebView2 自己的子窗里本来就有 3 个带 TR、1 个带 LAYERED（内部实现）；
#      旧「关」无脑整树 & ~TR，把这些本来就该有的样式也一并抹掉。
#   正解：**开之前逐窗快照原始 exstyle，关时按快照逐窗还原**（只动我们碰过的窗口，
#   其余窗口一律不碰）。这样 A→B→C 往返后顶层 exstyle 与新窗一模一样。
_CT_STATE = {"hwnd": 0, "on": False, "stop": None, "applied_h": 0}
_CT_SNAP = {"top": None, "kids": {}}          # top=(hwnd, exstyle) | kids={hwnd: exstyle}


def _enum_tree(hwnd):
    """返回 [顶层] + 全部后代句柄。"""
    import ctypes
    u32 = ctypes.windll.user32
    hs = [hwnd]
    proto = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)

    def _cb(ch, _lp):
        hs.append(ch)
        return True

    u32.EnumChildWindows(hwnd, proto(_cb), 0)
    return hs


def _apply_clickthrough_tree(hwnd):
    """给 hwnd 及其全部后代窗口挂 WS_EX_TRANSPARENT（幂等，可反复调用）。
    首次见到某个窗口时先记下它的原始 exstyle，供 _clear 精确还原。
    关键：WebView2 的内容位于子窗口（Chrome_WidgetWin_*）里，鼠标命中测试
    直接落在子窗口上——只给顶层窗挂样式无法穿透，必须整棵窗口树都挂。
    （子窗口带 WS_EX_TRANSPARENT 后 WM_NCHITTEST 返回 HTTRANSPARENT，
    命中落到父窗；父窗又是顶层 layered+transparent → 最终落到下层应用。）"""
    import ctypes
    u32 = ctypes.windll.user32
    GWL_EXSTYLE, TR, LAYERED = -20, 0x00000020, 0x00080000
    hwnd = int(hwnd)
    top = _CT_SNAP["top"]
    if top is None or top[0] != hwnd:      # 顶层句柄变了（窗口重建过）→ 重新快照，
        _CT_SNAP["top"] = (hwnd, u32.GetWindowLongW(hwnd, GWL_EXSTYLE))
    for h in _enum_tree(hwnd):
        if h not in _CT_SNAP["kids"]:
            _CT_SNAP["kids"][h] = u32.GetWindowLongW(h, GWL_EXSTYLE)
        ex = u32.GetWindowLongW(h, GWL_EXSTYLE)
        want = ex | TR | (LAYERED if h == hwnd else 0)
        # 已经挂过就不写：SetWindowLongW 会发 WM_STYLECHANGED，补挂线程是长期
        # 在跑的，每秒把同一份样式重写一遍纯属多余（还可能引起子窗口重绘）。
        if want != ex:
            u32.SetWindowLongW(h, GWL_EXSTYLE, want)


def _clear_clickthrough_tree(hwnd):
    """关掉穿透：**按快照把顶层与整棵子窗的 exstyle 精确还原**（幂等）。
    绝不「& ~TR」盲摘：那会误删 WebView2 子窗本来就带着的 TR/LAYERED，
    也会把为穿透临时挂上的顶层 WS_EX_LAYERED 留成「整窗全透明」空窗。"""
    import ctypes
    u32 = ctypes.windll.user32
    GWL_EXSTYLE, TR = -20, 0x00000020
    hwnd = int(hwnd)
    top = _CT_SNAP.get("top")
    if top and top[0] == hwnd:
        u32.SetWindowLongW(hwnd, GWL_EXSTYLE, top[1])
    else:                                  # 没快照过（异常路径）：只能保守摘 TR
        u32.SetWindowLongW(hwnd, GWL_EXSTYLE,
                           u32.GetWindowLongW(hwnd, GWL_EXSTYLE) & ~TR)
    kids = _CT_SNAP.get("kids") or {}
    for h, ex in list(kids.items()):
        try:
            if u32.IsWindow(h):
                u32.SetWindowLongW(h, GWL_EXSTYLE, ex)
        except Exception:                  # noqa: BLE001
            pass
    _CT_SNAP["top"] = None
    kids.clear()


_CT_LOCK = threading.Lock()          # 补挂线程 ⇄ 关穿透互斥，避免「刚关掉又被挂回去」


def _ct_keep_run(hwnd, stop):
    """穿透开着期间长期补挂（每 1 秒一次）。

    ⚠ 2026-09-28：原来只补挂 30 秒就收工。WebView2 的子窗口不一定在建窗时就
    齐活（换布局、渲染进程重建、GPU 进程重启都可能后建），30 秒后新建的子窗
    没有 WS_EX_TRANSPARENT → 命中测试落在它身上 → **穿透看起来「用久了就失效」**。
    现在只要还开着就一直补，配合 _apply 的「样式没变就不写」几乎没有开销。
    每次真挂之前复查状态，并在锁内操作：否则用户点「取消穿透」的瞬间，
    补挂线程可能正好把 TR 又挂回去（那一下之后小窗既不能点也不能拖）。
    """
    while not stop.is_set():
        time.sleep(1.0)
        if stop.is_set() or not _CT_STATE.get("on"):
            return
        try:
            with _CT_LOCK:
                if stop.is_set() or not _CT_STATE.get("on"):
                    return
                _apply_clickthrough_tree(hwnd)
        except Exception:               # noqa: BLE001
            pass


def _set_clickthrough(on, hwnd=0):
    """热切换鼠标穿透。on 与当前态相同则什么都不做；hwnd=0 时只记下来等窗口出现。

    ⚠ 2026-09-28 修正竞态：不能只看 `on == _CT_STATE["on"]` 就早退。
    `_ov_poller` 线程在 `webview.start()` 前就已启动，它的**第一轮**往往早于
    `shown` 事件——那时句柄还没到（hwnd=0），却把 `on` 记成了 True；等 `shown`
    带着真句柄再来时，早退判定「状态没变」直接 return，样式永远没挂上
    → 建窗即开启态的用户，新窗根本没有穿透（S2 实测暴露）。
    修法：额外记 `applied_h`（真正挂过样式的句柄）。只要「要开且这个句柄还没挂过」
    就补挂，不受状态相同的限制。"""
    on = bool(on)
    if hwnd:
        _CT_STATE["hwnd"] = int(hwnd)
    h = _CT_STATE.get("hwnd") or 0
    need = (on != _CT_STATE["on"]) or (on and h and _CT_STATE.get("applied_h") != h)
    if not need:
        return on
    _CT_STATE["on"] = on
    stop = _CT_STATE.get("stop")
    if stop is not None:                # 关掉上一次的补挂线程
        stop.set()
        _CT_STATE["stop"] = None
    try:
        if on and h:
            with _CT_LOCK:                      # 与补挂线程互斥（见 _ct_keep_run）
                _apply_clickthrough_tree(h)
            _CT_STATE["applied_h"] = h
            ev = threading.Event()
            _CT_STATE["stop"] = ev
            threading.Thread(target=_ct_keep_run, args=(h, ev), daemon=True).start()
        elif on:                        # 想开但窗口还没出来：记下意图，等句柄到了补挂
            _CT_STATE["applied_h"] = 0
        else:
            with _CT_LOCK:
                if h:
                    _clear_clickthrough_tree(h)
                else:                   # 还没有窗口：清掉可能残留的快照，下次重记
                    _CT_SNAP["top"] = None
                    _CT_SNAP["kids"].clear()
            _CT_STATE["applied_h"] = 0
    except Exception:                   # noqa: BLE001
        log("overlay child: 穿透热切换失败:\n" + traceback.format_exc())
    return on


def _tune_transparency(win):
    """让窗口底真正透出桌面：Win10 DWM 窗口合成属性
    （ACCENT_ENABLE_TRANSPARENTGRADIENT + 渐变色 alpha=0 → 窗体背景全透明），
    WebView2 的半透明卡片即可按"背景深度"滑条真实混合桌面颜色。
    （深色 BackColor 仅作 DWM 不可用机器上的兜底，防止白边回归）"""
    try:
        form = win.native
        from System.Drawing import Color
        form.BackColor = Color.FromArgb(10, 8, 14)   # 兜底深色
        hwnd = int(form.Handle.ToInt64())
        import ctypes

        # 让覆盖窗永不抢焦点：建窗即挂 WS_EX_NOACTIVATE。换布局重建小窗时，
        # 新窗口不会变成前台窗口，游戏/主程序焦点原样保留（键盘仍可正常打到游戏）。
        # 覆盖窗本就点击穿透、不接收交互，不激活它没有任何功能损失。
        try:
            _GWL_EXSTYLE, _WS_EX_NOACTIVATE = -20, 0x08000000
            _ex = ctypes.windll.user32.GetWindowLongW(hwnd, _GWL_EXSTYLE)
            if not (_ex & _WS_EX_NOACTIVATE):
                ctypes.windll.user32.SetWindowLongW(
                    hwnd, _GWL_EXSTYLE, _ex | _WS_EX_NOACTIVATE)
        except Exception:                                  # noqa: BLE001
            pass

        class ACCENT_POLICY(ctypes.Structure):
            _fields_ = [("AccentState", ctypes.c_int),
                        ("AccentFlags", ctypes.c_int),
                        ("GradientColor", ctypes.c_uint32),
                        ("AnimationId", ctypes.c_int)]

        class WCA_DATA(ctypes.Structure):
            _fields_ = [("Attrib", ctypes.c_int),
                        ("pvData", ctypes.c_void_p),
                        ("cbData", ctypes.c_size_t)]

        ACCENT_ENABLE_TRANSPARENTGRADIENT = 2
        WCA_ACCENT_POLICY = 19
        pol = ACCENT_POLICY(ACCENT_ENABLE_TRANSPARENTGRADIENT, 2, 0x00000000, 0)
        data = WCA_DATA(WCA_ACCENT_POLICY,
                        ctypes.cast(ctypes.byref(pol), ctypes.c_void_p),
                        ctypes.sizeof(pol))
        ok = ctypes.windll.user32.SetWindowCompositionAttribute(
            hwnd, ctypes.byref(data))
        # 去掉 DWM 阴影/圆角残留（frameless 窗口默认带一圈浅色光晕）
        import ctypes as _c
        try:
            ncrp = _c.c_int(1)                     # DWMNCRP_DISABLED
            ctypes.windll.dwmapi.DwmSetWindowAttribute(
                hwnd, 2, _c.byref(ncrp), 4)        # DWMWA_NCRENDERING_POLICY
            pref = _c.c_int(1)                     # DWMWCP_DONOTROUND
            ctypes.windll.dwmapi.DwmSetWindowAttribute(
                hwnd, 33, _c.byref(pref), 4)       # DWMWA_WINDOW_CORNER_PREFERENCE
        except Exception:                          # noqa: BLE001
            pass
        log("overlay child: DWM 透明合成 %s" %
            ("已生效" if ok else "不可用（深色兜底）"))
    except Exception:                                          # noqa: BLE001
        log("overlay child: 透明设置失败:\n" + traceback.format_exc())
    # ── 鼠标穿透（v2.3 优化 7）：建窗时按 ov_ct 挂一次；之后由 /api/ovpoll 下发
    # 最新值，子轮询线程发现变了就走 _set_clickthrough 热切，全程不重建窗口。
    try:
        _h = int(win.native.Handle.ToInt64())
        _ct = bool(ensure_ovcfg().get("ov_ct"))
        _set_clickthrough(_ct, _h)
        if _ct:
            log("overlay child: 鼠标穿透已开启 hwnd=%#x" % _h)
    except Exception:                                          # noqa: BLE001
        log("overlay child: 穿透设置失败:\n" + traceback.format_exc())


def _ov_do_show(form):
    """在 UI 线程里把隐藏的窗体 Show() 出来；返回是否真的执行了 Show（跨线程
    直接访问 WinForms 控件会抛异常，本函数只在 UI 线程经 form.Invoke 调用）。"""
    try:
        if not form.Visible:
            form.Show()
            return True
    except Exception:                                          # noqa: BLE001
        pass
    return False


def _ov_ensure_visible(win):
    """兜底强显：部分机器 WebView2 的 NavigationStarting 事件不触发，而 pywebview
    的透明无边框窗只在那个事件里 Show() —— 事件没来窗体就永久隐藏，表现成
    「覆盖开启不显示，切到 tkinter 透明才显示」。这里在 webview.start() 跑起后
    几秒内确认窗体可见，隐藏就强制 Show()，兜住那条失效的显示路径。

    ⚠ WinForms 控件只能在创建它的 UI 线程访问，必须用 form.Invoke 把 Show() 派发
    回 UI 线程，否则 .NET 抛跨线程异常且窗体依旧隐藏（修复会静默失效）。
    """
    import time as _t
    try:
        import clr
        import System
        _Func = System.Func[bool]

        def _invoke(f):
            return f.Invoke(_Func(lambda: _ov_do_show(f)))
    except Exception:                                          # noqa: BLE001
        _invoke = None
    deadline = _t.time() + 8.0
    while _t.time() < deadline:
        _t.sleep(0.3)
        try:
            form = getattr(win, "native", None)
            if form is None:
                continue
            if _invoke is not None:
                if _invoke(form):                  # 在 UI 线程里判断隐藏并 Show
                    log("overlay child: 兜底强制显示窗体（WebView2 导航事件未触发）")
                break                              # 已确认/已强显，无需继续轮询
            else:
                if _ov_do_show(form):
                    log("overlay child: 兜底强制显示窗体")
                break
        except Exception:                                      # noqa: BLE001
            pass


def run_overlay_child():
    args = sys.argv[1:]
    url = ""
    if "--url" in args:
        url = args[args.index("--url") + 1]
    if not url:
        return
    # 落点：精确坐标优先；没存过就按「预设位置」（左上/右上/左下/右下）算
    try:
        _cfg = ensure_ovcfg()
    except Exception:                                          # noqa: BLE001
        _cfg = {}
    x, y = ov_start_xy(_cfg)
    import webview
    log("overlay child: 准备创建覆盖窗口 url=%s x=%s y=%s" % (url, x, y))
    kw = {"x": x, "y": y}
    win = webview.create_window(
        "FYS 屏幕覆盖", url.rstrip("/") + "/overlay",
        width=360, height=200, resizable=False,
        frameless=True, on_top=True, transparent=True,
        shadow=False, **kw)               # shadow=False：去掉 DWM 窗口阴影光晕（0% 背景时的浅白圈）
    threading.Thread(target=_ov_poller, args=(win, url), daemon=True).start()
    win.events.shown += lambda: (_tune_transparency(win),
                                 log("overlay child: 窗口已显示"))
    # Bug B 兜底：WebView2 导航事件可能不触发导致窗体永久隐藏，另起线程强显
    threading.Thread(target=_ov_ensure_visible, args=(win,), daemon=True).start()
    webview.start()
    log("overlay child: 消息循环退出")


# ── 覆盖子进程入口（--overlay-tk）：原生分层窗口，逐像素 alpha ──
# 旧实现是 tkinter transparentcolor 颜色键：把品红像素抠成全透明。
# 缺陷：ClearType 抗锯齿边缘 = 文字色与品红底的混色，抠图后留粉色描边，无法避免。
# 现改为 PIL 离屏渲染 + UpdateLayeredWindow：真逐像素 alpha，文字平滑无描边，
# 背景深度 > 0 时还能画真半透明圆角卡片（与无边框窗一致）。入口名保留 --overlay-tk。
TK_CARD = (20, 17, 28)         # 卡片底色（与网页版 --card 一致）


def _tk_http(base, path, timeout=3):
    import urllib.request
    op = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    with op.open(base.rstrip("/") + path, timeout=timeout) as r:
        return json.load(r)


def _tk_post(base, path):
    import urllib.request
    op = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    try:
        op.open(base.rstrip("/") + path, timeout=3).read()
    except Exception:                                          # noqa: BLE001
        pass


_OVGDI_CACHE = {}          # px -> (常规, 粗体)，见 _ovgdi_fonts


def _ovgdi_fonts(px):
    """微软雅黑常规/粗体；找不到就退到 PIL 内置位图字体（不能传字体名，
    ImageFont.truetype 只认文件路径，传名字会直接抛 OSError → 覆盖窗永远空白）。

    小号字用 round 而不是 int：页面侧用的是 Math.round，int 截断会让
    size=30 时一边 18px 一边 19px。

    按字号缓存。覆盖窗 tick 每 0.35 秒重绘一次，而字号/字体在一轮内
    根本不变 —— 原来每帧都要做 4 次 os.path.exists + 2 次 TTF 解析（几十毫秒）。
    """
    hit = _OVGDI_CACHE.get(px)
    if hit is not None:
        return hit
    from PIL import ImageFont
    reg = None
    for p in (r"C:\Windows\Fonts\msyh.ttc", r"C:\Windows\Fonts\msyh.ttf",
              r"C:\Windows\Fonts\simhei.ttf"):
        if os.path.exists(p):
            reg = p
            break
    bold = r"C:\Windows\Fonts\msyhbd.ttc"
    if not os.path.exists(bold):
        bold = reg
    try:
        out = (ImageFont.truetype(reg, max(9, round(px * 0.62))),
               ImageFont.truetype(bold, max(11, round(px))))
    except OSError:
        f = ImageFont.load_default()
        out = (f, f)
    _OVGDI_CACHE[px] = out
    return out


def run_overlay_tk_child():
    args = sys.argv[1:]
    url = ""
    if "--url" in args:
        url = args[args.index("--url") + 1]
    if not url:
        return
    base = url.rstrip("/")

    import ctypes
    from ctypes import wintypes
    import mapnames
    from PIL import Image, ImageChops, ImageDraw, ImageOps

    user32 = ctypes.windll.user32
    gdi32 = ctypes.windll.gdi32
    kernel32 = ctypes.windll.kernel32
    user32.SetProcessDPIAware()

    HWND, UINT = wintypes.HWND, wintypes.UINT
    WPARAM, LPARAM = wintypes.WPARAM, wintypes.LPARAM
    LRESULT = ctypes.c_ssize_t
    WM_CLOSE, WM_DESTROY, WM_NCHITTEST = 0x10, 0x02, 0x84
    WM_LBUTTONDOWN, WM_EXITSIZEMOVE = 0x0201, 0x0232
    HTCLIENT, HTCAPTION = 1, 2
    ULW_ALPHA = 2
    WS_POPUP, WS_VISIBLE = 0x80000000, 0x10000000
    WS_EX_LAYERED, WS_EX_TOPMOST, WS_EX_TOOLWINDOW = 0x80000, 8, 0x80

    class POINT(ctypes.Structure):
        _fields_ = [("x", ctypes.c_long), ("y", ctypes.c_long)]

    class SIZE(ctypes.Structure):
        _fields_ = [("cx", ctypes.c_long), ("cy", ctypes.c_long)]

    class BLENDFUNCTION(ctypes.Structure):
        _fields_ = [("BlendOp", ctypes.c_byte), ("BlendFlags", ctypes.c_byte),
                    ("SourceConstantAlpha", ctypes.c_byte),
                    ("AlphaFormat", ctypes.c_byte)]

    class BMIH(ctypes.Structure):
        _fields_ = [("biSize", wintypes.DWORD), ("biWidth", wintypes.LONG),
                    ("biHeight", wintypes.LONG), ("biPlanes", wintypes.WORD),
                    ("biBitCount", wintypes.WORD), ("biCompression", wintypes.DWORD),
                    ("biSizeImage", wintypes.DWORD), ("biXPelsPerMeter", wintypes.LONG),
                    ("biYPelsPerMeter", wintypes.LONG), ("biClrUsed", wintypes.DWORD),
                    ("biClrImportant", wintypes.DWORD)]

    class BMI(ctypes.Structure):
        _fields_ = [("bmiHeader", BMIH), ("bmiColors", wintypes.DWORD * 3)]

    WNDPROC = ctypes.WINFUNCTYPE(LRESULT, HWND, UINT, WPARAM, LPARAM)

    class WNDCLASSW(ctypes.Structure):
        _fields_ = [("style", UINT), ("lpfnWndProc", WNDPROC),
                    ("cbClsExtra", ctypes.c_int), ("cbWndExtra", ctypes.c_int),
                    ("hInstance", wintypes.HINSTANCE), ("hIcon", wintypes.HICON),
                    ("hCursor", wintypes.HANDLE), ("hbrBackground", wintypes.HBRUSH),
                    ("lpszMenuName", wintypes.LPCWSTR),
                    ("lpszClassName", wintypes.LPCWSTR)]

    user32.DefWindowProcW.restype = LRESULT
    user32.DefWindowProcW.argtypes = [HWND, UINT, WPARAM, LPARAM]

    cfg = {"show": {}, "color": "#ffffff", "size": 30, "bg": 0.55, "x": None, "y": None}
    try:
        disk = _tk_http(base, "/api/ovcfg").get("cfg") or {}
        for k in ("color", "size", "bg", "x", "y", "ov_ct", "layout",
                  "skin", "skin_ts", "skin_op"):
            if k in disk:
                cfg[k] = disk[k]
        if isinstance(disk.get("show"), dict):
            cfg["show"] = disk["show"]
    except Exception:                                          # noqa: BLE001
        pass

    SEP = "━━━━━━━━━━━━━━"
    NAME = {"map": "地图名称：", "mapcn": "译　名：", "stage": "当前关卡：",
            "passes": "通关云点：", "dmgrank": "伤害云点：",
            "econ": "通关龙晶：", "dmgecon": "伤害龙晶："}
    GRP_A = ["map", "mapcn", "stage"]
    GRP_B = ["passes", "dmgrank", "econ", "dmgecon"]

    def wan(v):
        """伤害/分数统一按「万」：≥1000 才换算，1 位小数（与页面 wan() 同规则）。"""
        if v is None:
            return "—"
        try:
            v = float(v)
        except (TypeError, ValueError):
            return str(v)
        if v < 1000:
            return "%g" % v
        # floor(x+0.5) 而不是 Python 内置 round：内置是银行家舍入，2500 会算成 0.2w，
        # 与页面 JS 的 Math.round（0.3w）对不上，覆盖窗和主界面会显示不同数字
        x = math.floor(v / 10000 * 10 + 0.5) / 10
        return ("%g" % x) + "w"

    def val(k, d):
        c = d.get("current") or {}
        if k == "map":
            return d.get("map") or "—"
        if k == "mapcn":
            return d.get("mapcn") or mapnames.cn(d.get("map") or "") or "—"
        if k == "stage":
            return ("第 %s / %s 关" % (d.get("stage"), d.get("total_stages") or "?")
                    if d.get("stage") else "关卡 —")
        lv = d.get("live") or {}

        def _extra(k):
            """括号里的推算值（没有 GSI 本局数据就不显示括号）：
               · 伤害云点 / 伤害龙晶 → 距「下一档兑换」还差多少伤害（例 2.4w（0.3w））
               · 通关云点 / 通关龙晶 → 本局伤害换到的个数（例 13（1↑），0 也显示）"""
            if not lv:
                return ""
            if k == "passes":
                v = lv.get("rankPts")
                return "（%s↑）" % (v if v is not None else 0) if v is not None else ""
            if k == "econ":
                v = lv.get("econPts")
                return "（%s↑）" % (v if v is not None else 0) if v is not None else ""
            if k in ("dmgrank", "dmgecon"):
                ratio = c.get("rankDamage") if k == "dmgrank" else c.get("econDamage")
                dmg = lv.get("dmg")
                if not isinstance(ratio, int) or ratio <= 0 or dmg is None:
                    return ""
                need = ratio - (dmg % ratio)
                return "（%s）" % wan(need)
            return ""

        if k == "passes":
            v = c.get("rankPasses", "—") if c.get("rankPasses") is not None else "—"
            return "%s%s" % (v, _extra(k))
        if k == "dmgrank":
            return "%s%s" % (wan(c.get("rankDamage")), _extra(k))
        if k == "econ":
            v = c.get("econPasses", "—") if c.get("econPasses") is not None else "—"
            return "%s%s" % (v, _extra(k))
        if k == "dmgecon":
            return "%s%s" % (wan(c.get("econDamage")), _extra(k))
        return "—"

    def rgb():
        h = (cfg.get("color") or "#ffffff").lstrip("#")
        try:
            return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))
        except (ValueError, IndexError):
            return (255, 255, 255)

    # ── 窗口 ──
    close_off = [10 ** 6, 10 ** 6, 0, 0]          # × 命中区（客户区坐标）
    hwnd_ref = [None]

    def in_close(h, x, y):
        """x,y 必须是**屏幕坐标**：WM_NCHITTEST 的 lParam 就是屏幕坐标，
        而 WM_LBUTTONDOWN 的 lParam 是客户区坐标（下面先 ClientToScreen 再判断）。"""
        rc = wintypes.RECT()
        user32.GetWindowRect(h, ctypes.byref(rc))
        return (rc.left + close_off[0] <= x <= rc.left + close_off[2]
                and rc.top + close_off[1] <= y <= rc.top + close_off[3])

    def wndproc(h, msg, wp, lp):
        if msg == WM_NCHITTEST:
            x = ctypes.c_short(lp & 0xFFFF).value
            y = ctypes.c_short((lp >> 16) & 0xFFFF).value
            return HTCLIENT if in_close(h, x, y) else HTCAPTION
        if msg == WM_LBUTTONDOWN:
            # 客户区坐标 → 屏幕坐标，否则窗口不在屏幕左上角时 × 永远点不中
            pt = POINT(*mouse_xy(lp))
            user32.ClientToScreen(h, ctypes.byref(pt))
            if in_close(h, pt.x, pt.y):
                user32.PostMessageW(h, WM_CLOSE, 0, 0)
                return 0
        if msg == WM_EXITSIZEMOVE:
            rc = wintypes.RECT()
            user32.GetWindowRect(h, ctypes.byref(rc))

            def _save():
                _tk_post(base, "/api/ctl?do=ovtkpos&x=%d&y=%d"
                         % (rc.left, rc.top))
            threading.Thread(target=_save, daemon=True).start()
            return 0
        if msg == WM_DESTROY:
            user32.PostQuitMessage(0)
            return 0
        return user32.DefWindowProcW(h, msg, wp, lp)

    def mouse_xy(lp):
        return (ctypes.c_short(lp & 0xFFFF).value,
                ctypes.c_short((lp >> 16) & 0xFFFF).value)

    wndproc_ref = WNDPROC(wndproc)
    hinst = wintypes.HINSTANCE(kernel32.GetModuleHandleW(None))
    wc = WNDCLASSW()
    wc.lpfnWndProc = wndproc_ref
    wc.hInstance = hinst
    wc.lpszClassName = "FysOverlayNative"
    user32.RegisterClassW(ctypes.byref(wc))
    x0, y0 = ov_start_xy(cfg)
    hwnd = user32.CreateWindowExW(
        WS_EX_LAYERED | WS_EX_TOPMOST | WS_EX_TOOLWINDOW, "FysOverlayNative", "",
        WS_POPUP | WS_VISIBLE, x0, y0, 10, 10, None, None, hinst, None)
    hwnd_ref[0] = hwnd
    if not hwnd:
        log("overlay-tk child: 建窗失败")
        return
    # ── 鼠标穿透（2026-09-28 修正）：**必须走 _set_clickthrough**，让状态机记上
    # 「当前开着」（快照 + _CT_STATE["on"]=True）。原实现直接 SetWindowLongW 挂样式，
    # 绕过了状态机 —— cfg_tick 又只在「值变化」时才调 _set_clickthrough，于是用户在
    # 设置页取消勾选时，_set_clickthrough(False) 发现 on(False)==state(False) 直接
    # return，TR 永远摘不掉 → 小窗既不能点也不能拖（用户实测报的正是这个）。──
    try:
        _set_clickthrough(bool(cfg.get("ov_ct")), hwnd)
        if cfg.get("ov_ct"):
            log("overlay-tk child: 鼠标穿透已开启")
    except Exception:                                          # noqa: BLE001
        log("overlay-tk child: 穿透设置失败:\n" + traceback.format_exc())

    # ── 渲染 + 上屏 ──
    hdc_screen = user32.GetDC(None)
    memdc = gdi32.CreateCompatibleDC(hdc_screen)

    def blit(img):
        w, h = img.size
        raw = img.tobytes()
        out = bytearray(len(raw))
        for i in range(0, len(raw), 4):        # RGBA -> 预乘 BGRA
            r0, g0, b0, a0 = raw[i], raw[i + 1], raw[i + 2], raw[i + 3]
            if a0 == 255:
                out[i], out[i + 1], out[i + 2], out[i + 3] = b0, g0, r0, a0
            elif a0:
                out[i] = b0 * a0 // 255
                out[i + 1] = g0 * a0 // 255
                out[i + 2] = r0 * a0 // 255
                out[i + 3] = a0
        bi = BMI()
        bi.bmiHeader.biSize = ctypes.sizeof(BMIH)
        bi.bmiHeader.biWidth = w
        bi.bmiHeader.biHeight = -h
        bi.bmiHeader.biPlanes = 1
        bi.bmiHeader.biBitCount = 32
        bits = ctypes.c_void_p()
        hbmp = gdi32.CreateDIBSection(hdc_screen, ctypes.byref(bi), 0,
                                      ctypes.byref(bits), None, 0)
        if not hbmp or not bits:
            return
        ctypes.memmove(bits, bytes(out), len(out))
        old = gdi32.SelectObject(memdc, hbmp)
        rc = wintypes.RECT()
        user32.GetWindowRect(hwnd, ctypes.byref(rc))
        pt = POINT(rc.left, rc.top)
        sz = SIZE(w, h)
        ptsrc = POINT(0, 0)
        blend = BLENDFUNCTION(0, 0, 255, 1)
        user32.UpdateLayeredWindow(hwnd, hdc_screen, ctypes.byref(pt),
                                   ctypes.byref(sz), memdc, ctypes.byref(ptsrc),
                                   0, ctypes.byref(blend), ULW_ALPHA)
        gdi32.SelectObject(memdc, old)
        gdi32.DeleteObject(hbmp)

    # ── iconic（地图图标）布局：封面竖条 + 地图名 + 数值列（与网页版同构）──
    _ico_cache = {"k": None, "img": None}

    def _ico_strip(m, cw, ch):
        """封面**铺满左列**的竖条（等比裁剪居中，不是缩成一条贴在顶部）。
        按 (地图名, 宽, 高) 缓存：tick 每 0.35s 重绘，不能每帧都开 JPEG + 重采样。
        没有封面返回 None（调用方画占位块）。"""
        key = (str(m).lower(), cw, ch)
        if _ico_cache["k"] == key:
            return _ico_cache["img"]
        img = None
        try:
            p = find_cover(key[0] + ".jpg")
            if p:
                from PIL import ImageOps
                im = Image.open(p).convert("RGBA")
                img = ImageOps.fit(im, (cw, ch), method=Image.LANCZOS,
                                   centering=(0.5, 0.42))
        except Exception:                                  # noqa: BLE001
            img = None                                     # 图坏了当没有，走占位块
        _ico_cache["k"] = key
        _ico_cache["img"] = img
        return img

    def render_iconic(d, show, col):
        try:
            px = float(cfg.get("size") or 30)
        except (TypeError, ValueError):
            px = 30.0
        px = max(8.0, min(160.0, px))
        spx = max(9, round(px * 0.5))          # 小号字（副行 / 数值标签）
        f_small = _ovgdi_fonts(spx)[0]
        f_title = _ovgdi_fonts(px)[1]          # 粗体
        f_val = _ovgdi_fonts(px)[1]
        gold = (255, 206, 122)                 # 通关系列金色（与网页版 .g 一致）
        scratch = ImageDraw.Draw(Image.new("RGBA", (8, 8)))

        def tw(t, f):
            return scratch.textlength(str(t), font=f)

        pad = 12
        cover_w = max(40, int(px * 1.5))

        # 左列标签（ze_ 前缀去掉，取前 8 个字符）
        m = str(d.get("map") or "")
        tag = (m[3:11].upper() if m[:3].lower() == "ze_" else m.upper()[:8]) or "MAP"

        # 右块内容（全部按显示开关裁剪，与网页版 iconic 同规则）
        title = (str(val("map", d)) if show.get("map", True)
                 else (str(val("mapcn", d)) if show.get("mapcn") else "—"))
        sub_parts = []
        if show.get("mapcn"):
            sub_parts.append(str(val("mapcn", d)))
        if show.get("stage"):
            sub_parts.append(str(val("stage", d)))
        sub = " · ".join(sub_parts)
        nums = []
        for k, lb in (("passes", "通关云点"), ("dmgrank", "伤害云点"),
                      ("econ", "通关龙晶"), ("dmgecon", "伤害龙晶")):
            if show.get(k):
                nums.append((lb, str(val(k, d)), gold if k in ("passes", "econ") else col))

        lh_t = int(px * 1.25)
        lh_s = int(spx * 1.5)
        widths = [tw(title, f_title)]
        if sub:
            widths.append(tw(sub, f_small))
        if nums:
            widths.append(sum(max(tw(lb, f_small), tw(v, f_val))
                              for lb, v, _ in nums) + 10 * max(0, len(nums) - 1))
        text_w = int(max(widths)) if widths else 40
        text_h = lh_t + (lh_s if sub else 0) + (int(spx * 1.3) + lh_t if nums else 0)

        col_w = cover_w
        col_h = max(text_h, int(px * 2.6))     # 竖条至少这么高，别缩成小方块
        w = pad + col_w + 12 + text_w + pad + 18
        h = col_h + pad * 2

        img = Image.new("RGBA", (w, h), (0, 0, 0, 0))
        dr = ImageDraw.Draw(img)
        try:
            bg = float(cfg.get("bg") or 0)
        except (TypeError, ValueError):
            bg = 0.0
        bg = max(0.0, min(1.0, bg))
        if bg >= 0.03:
            r = min(16, w // 2, h // 2)
            dr.rounded_rectangle([3, 3, w - 4, h - 4], radius=r,
                                 fill=TK_CARD + (int(255 * bg),))
        # 左列：封面**竖条铺满整列**（底部压半透明带放地图标签），没有封面画占位块
        band_h = max(16, int(spx * 1.7))
        radius = min(13, cover_w // 2, col_h // 2)
        mask = Image.new("L", (cover_w, col_h), 0)
        ImageDraw.Draw(mask).rounded_rectangle(
            [0, 0, cover_w - 1, col_h - 1], radius=radius, fill=255)
        strip = _ico_strip(m, cover_w, col_h)
        if strip is not None:
            strip = strip.copy()               # 缓存对象不能就地改（每帧会叠标签）
            drs = ImageDraw.Draw(strip)
            drs.rectangle([0, col_h - band_h, cover_w, col_h], fill=(0, 0, 0, 125))
            tw_tag = tw(tag, f_small)
            drs.text(((cover_w - tw_tag) // 2, col_h - band_h + (band_h - spx) // 2 - 2),
                     tag, font=f_small, fill=(255, 255, 255, 230))
        else:
            strip = Image.new("RGBA", (cover_w, col_h), (255, 255, 255, 26))
            drs = ImageDraw.Draw(strip)
            tw_tag = tw(tag, f_small)
            drs.text(((cover_w - tw_tag) // 2, (col_h - spx) // 2),
                     tag, font=f_small, fill=col + (185,))
        img.paste(strip, (pad, pad), mask)
        # 右块
        tx = pad + col_w + 12
        y = pad + 2
        dr.text((tx, y), title, font=f_title, fill=col + (255,))
        y += lh_t
        if sub:
            dr.text((tx, y), sub, font=f_small, fill=col + (165,))
            y += lh_s
        if nums:
            y += 2
            for lb, v, c in nums:
                nw = max(tw(lb, f_small), tw(v, f_val))
                dr.text((tx, y), lb, font=f_small, fill=col + (165,))
                dr.text((tx, y + int(spx * 1.3)), v, font=f_val, fill=c + (255,))
                tx += int(nw) + 10
        # × 关闭按钮（右上角，命中区与卡片布局同款）
        dr.text((w - 22, 8), "×", font=f_title, fill=col + (150,))
        close_off[:] = [w - 30, 2, w - 6, 28]
        blit(img)

    # ── skin（自定义底图）布局：底图铺满卡片 + 整层真透明（与网页版同规则）──
    _skin_cache = {"k": None, "img": None}

    def _skin_img(cw, ch):
        """按卡片内框尺寸 cover 裁底图（缓存），文件缺失/读坏返回 None。

        底图是服务端按「取景框」裁好的成品（data\\overlay_skin.png），这里只做
        等比铺满（居中裁剪）。tick 每 0.35s 重绘，必须缓存，否则每帧开图 +
        LANCZOS 重采样要几十毫秒，小窗会拖影。
        """
        key = (cw, ch, cfg.get("skin"), cfg.get("skin_ts"))
        if _skin_cache["k"] == key:
            return _skin_cache["img"]
        img = None
        try:
            p = _ovskin_path()
            if cfg.get("skin") and os.path.exists(p):
                im = Image.open(p).convert("RGBA")
                img = ImageOps.fit(im, (cw, ch), method=Image.LANCZOS,
                                   centering=(0.5, 0.5))
        except Exception:                                  # noqa: BLE001
            img = None                                     # 图坏了当没有，走卡片底
            log("overlay-tk child: 底图加载失败:\n" + traceback.format_exc())
        _skin_cache["k"] = key
        _skin_cache["img"] = img
        return img

    def render(d):
        show = cfg.get("show") or {}
        col = rgb()
        # tkinter 四档布局全支持：card / compact / iconic / skin（v2.15 起 skin
        # 不再回落卡片 —— 原生分层窗按同规则画底图 + 暗化层）
        layout = cfg.get("layout") or "card"
        compact = (layout == "compact")
        skin_mode = (layout == "skin")
        if layout == "iconic" and d.get("map"):
            return render_iconic(d, show, col)
        rows_a = [k for k in GRP_A if show.get(k, True)]
        rows_b = [k for k in GRP_B if show.get(k, True)]
        items = []
        if d.get("map"):
            if compact:
                # 单行胶囊：地图 · 关卡 · 云点 13/2.4w · 龙晶 10/3.5w（按显示开关裁剪）
                segs = [str(val(k, d)) for k in rows_a]
                if "passes" in rows_b or "dmgrank" in rows_b:
                    a = str(val("passes", d)) if "passes" in rows_b else None
                    b = str(val("dmgrank", d)) if "dmgrank" in rows_b else None
                    segs.append("云点 %s" % ("/".join(x for x in (a, b) if x is not None)
                                             if (a or b) else "—"))
                if "econ" in rows_b or "dmgecon" in rows_b:
                    a = str(val("econ", d)) if "econ" in rows_b else None
                    b = str(val("dmgecon", d)) if "dmgecon" in rows_b else None
                    segs.append("龙晶 %s" % ("/".join(x for x in (a, b) if x is not None)
                                             if (a or b) else "—"))
                items.append(("flat", " · ".join(segs) if segs else
                              "屏幕覆盖：请在主窗口选择显示内容"))
            else:
                for k in rows_a:
                    items.append(("row", (NAME[k], val(k, d))))
                if rows_a and rows_b:
                    items.append(("sep", SEP))
                for k in rows_b:
                    items.append(("row", (NAME[k], val(k, d))))
        else:
            # 未进服 / 查询不到：只留一行紧凑状态，
            # 不再把「地图 —、关卡 —…」整列摆出来（以前一掉线就满屏横杠）
            items.append(("state", "· " + (d.get("state_text") or "未进入服务器")))
        if not items:
            items.append(("state", "屏幕覆盖：请在主窗口选择显示内容"))
        # 自定义底图但还没上传：照网页版一样给一行提示（虚线卡片）
        has_skin = bool(cfg.get("skin")) and os.path.exists(_ovskin_path())
        if skin_mode and not has_skin:
            items.append(("state", "🖼️ 在设置页上传底图，这里就显示你的图片"))

        try:                                   # 配置被手工改坏时不要每帧抛异常
            px = float(cfg.get("size") or 30)
        except (TypeError, ValueError):
            px = 30.0
        px = max(8.0, min(160.0, px))
        f_label, f_value = _ovgdi_fonts(px)
        f_x = f_label
        lh = int(px * 1.55)
        pad = 14
        scratch = ImageDraw.Draw(Image.new("RGBA", (8, 8)))

        def tw(t, f):
            return scratch.textlength(t, font=f)

        w = 120
        for kind, t in items:
            if kind == "row":
                w = max(w, tw(t[0], f_label) + 8 + tw(str(t[1]), f_value))
            elif kind == "flat":
                w = max(w, tw(str(t), f_value) + 12)
            else:
                w = max(w, tw(t, f_label))
        w = int(w) + pad * 2 + 16
        h = int(10 + lh * len(items) + 8)
        if skin_mode:
            w = max(w, 260)                    # 底图布局给点横向空间，不然只剩一条

        img = Image.new("RGBA", (w, h), (0, 0, 0, 0))
        dr = ImageDraw.Draw(img)
        try:
            bg = float(cfg.get("bg") or 0)
        except (TypeError, ValueError):
            bg = 0.0
        bg = max(0.0, min(1.0, bg))
        skin_drawn = False
        if skin_mode and has_skin:
            # 真半透明：底图按「底图透明度」整层淡出（op 越大越透，桌面/游戏
            # 透得过来）；文字在不透明前景，靠阴影保证可读 —— 与网页版 ::before
            # 层 opacity 同规则。旧实现是叠加暗化层，图始终不透明（2026-11 修）。
            inner = _skin_img(w - 6, h - 6)
            if inner is not None:
                try:
                    op = int(float(cfg.get("skin_op") or 62))
                except (TypeError, ValueError):
                    op = 62
                alpha = 1.0 - max(20, min(95, op)) / 100.0
                r = min(16, (w - 6) // 2, (h - 6) // 2)
                mask = Image.new("L", (w - 6, h - 6), 0)
                ImageDraw.Draw(mask).rounded_rectangle(
                    [0, 0, w - 7, h - 7], radius=r, fill=255)
                if alpha < 0.999:
                    # 圆角遮罩 × 整层 alpha：一次 paste 同时拿到圆角与半透明
                    mask = ImageChops.multiply(
                        mask, Image.new("L", mask.size, int(255 * alpha)))
                img.paste(inner, (3, 3), mask)
                dr.rounded_rectangle([3, 3, w - 4, h - 4], radius=r,
                                     outline=(255, 255, 255, 71), width=1)
                skin_drawn = True
        if not skin_drawn and bg >= 0.03:      # 半透明圆角卡片
            r = min(14, w // 2, h // 2)
            dr.rounded_rectangle([3, 3, w - 4, h - 4], radius=r,
                                 fill=TK_CARD + (int(255 * bg),))
        y = 10

        def txt(xy, s, font, fill):
            """底图是半透明的（后面可能是游戏画面）：先描暗影再写字，
            对应网页版的 text-shadow；非 skin 布局不加，保持原来的干净边缘。"""
            if skin_drawn:
                dr.text((xy[0] + 1, xy[1] + 1), s, font=font, fill=(0, 0, 0, 205))
                dr.text((xy[0] + 1, xy[1] + 2), s, font=font, fill=(0, 0, 0, 90))
            dr.text(xy, s, font=font, fill=fill)

        for kind, t in items:
            if kind == "row":
                lb, vv = t
                txt((pad, y), lb, f_label, col + (215,))
                xl = pad + int(tw(lb, f_label)) + 8
                txt((xl, y), str(vv), f_value, col + (255,))
            elif kind == "flat":
                txt((pad, y), str(t), f_value, col + (255,))
            elif kind == "sep":
                txt((pad, y), t, f_label, col + (95,))
            else:
                txt((pad, y), t, f_label, col + (185,))
            y += lh
        # × 关闭按钮（右上角）
        txt((w - 22, 8), "×", f_x, col + (150,))
        close_off[:] = [w - 30, 2, w - 6, 28]
        blit(img)

    def tick():
        fails = 0
        while True:
            try:
                # 超时给到 6s：/api/status 内部可能在做 A2S 多轮重试（最坏 ~3s）
                d = _tk_http(base, "/api/status", timeout=6)
                fails = 0
                render(d)
            except Exception:                                  # noqa: BLE001
                fails += 1
                if fails == 1:
                    log("overlay-tk tick 异常\n" + traceback.format_exc())
                if fails > 16:                 # 主程序不在了 -> 自动退出（16×0.5≈8s 同旧版）
                    user32.PostMessageW(hwnd, WM_CLOSE, 0, 0)
                    return
            try:
                if _tk_http(base, "/api/ovpoll").get("close"):
                    user32.PostMessageW(hwnd, WM_CLOSE, 0, 0)
                    return
            except Exception:                                  # noqa: BLE001
                pass
            time.sleep(0.35)   # 1.0→0.35：关闭指令下一轮才被看到，太慢拖慢重启

    def cfg_tick():
        last_ct = bool(cfg.get("ov_ct"))
        while True:
            try:
                disk = (_tk_http(base, "/api/ovcfg").get("cfg") or {})
                for k in ("color", "size", "bg", "layout",
                          "skin", "skin_ts", "skin_op"):
                    if k in disk:
                        cfg[k] = disk[k]
                if isinstance(disk.get("show"), dict):
                    cfg["show"] = disk["show"]
                # 鼠标穿透热切（v2.3 优化 7）：tkinter 窗同样不重建，只改扩展样式
                _tk_ct = bool(disk.get("ov_ct"))
                if _tk_ct != last_ct:
                    last_ct = _tk_ct
                    _set_clickthrough(_tk_ct, hwnd)
            except Exception:                                  # noqa: BLE001
                pass
            time.sleep(2.0)

    log("overlay-tk child: 启动（原生分层窗口） base=%s" % base)
    threading.Thread(target=tick, daemon=True).start()
    threading.Thread(target=cfg_tick, daemon=True).start()
    msg = wintypes.MSG()
    while user32.GetMessageW(ctypes.byref(msg), None, 0, 0) > 0:
        user32.TranslateMessage(ctypes.byref(msg))
        user32.DispatchMessageW(ctypes.byref(msg))
    rc = wintypes.RECT()
    user32.GetWindowRect(hwnd, ctypes.byref(rc))
    _tk_post(base, "/api/ctl?do=ovtkpos&x=%d&y=%d" % (rc.left, rc.top))
    user32.ReleaseDC(None, hdc_screen)
    gdi32.DeleteDC(memdc)
    log("overlay-tk child: 退出")


_SYNC_START_LOCK = threading.Lock()    # 只护「检查 running + 置位」这一小段


def _sync_worker():
    """后台从 GitHub 重新拉取 fyscs/cs2 仓库并重建地图数据索引。"""
    # 手动（do=sync 起线程）与自动（repo_check 直调）两条路都汇到这里。
    # 检查+置位必须原子：两线程同时通过 running 检查会双跑（重复下载重建）。
    with _SYNC_START_LOCK:
        if State.sync.get("running"):
            return                              # 已有同步在跑（撞车保护）
        State.sync.update(running=True, ok=None, msg="正在从 GitHub 拉取 fyscs/cs2 …",
                          at=time.strftime("%H:%M:%S"), pct=3)

    def _prog(text, pct):
        """把 build 的阶段进度写进 State.sync（前端每秒轮询 /api/status 显示）。"""
        State.sync.update(msg=text, pct=pct)

    try:
        meta = State.engine.load_state(force=True, progress=_prog)
        # 同步完本地数据就是最新的了，这轮「官方数据有更新」提醒的使命结束，
        # 横幅该消失。⚠ 不能指望 diff 自己清零：build(force=True) 写下的 diff
        # 是「同步前旧缓存 vs 上游」的差异，总量不会变成 0；而后台定时检测
        # 对空 diff 又会保留未读提醒。两边都不置 seen 的话，用户点完「立即应用」
        # 横幅依旧挂着，看起来像没同步成功。
        try:
            State.engine.diff_mark_seen()
        except Exception:                                  # noqa: BLE001
            pass
        State.sync.update(running=False, ok=True, pct=100,
                          msg="同步完成：地图 %s 张 / 关卡 %s 段（%s）"
                              % (meta.get("maps"), meta.get("stages"),
                                 meta.get("built_at_str", "")))
        # v2.14：同步顺带把「新图没有封面」补上 —— 直连风云社官方图床
        # resx.fyscs.cn/mapimgs/（公开 CDN，不是已停用的那台中转服务器）。
        # 后台线程，不挡同步完成提示；同步里来新图 → 玩家这边自己就有封面，
        # 不必等发版。失败只是少张图（前端回退默认底纹），不影响数据。
        try:
            cover_sync()
        except Exception as e:                             # noqa: BLE001
            log("cover-sync: 触发失败 %r" % (e,))
    except Exception as e:                                     # noqa: BLE001
        State.sync.update(running=False, ok=False, pct=0,
                          msg="同步失败（%s），继续使用本地缓存。" % e)


def _hwnd():
    """无边框窗口的原生句柄（WinForms 后端）。
    注意：pythonnet 的 IntPtr 不能直接 int()，必须走 ToInt64/ToInt32。"""
    h = State.win.native.Handle if State.win is not None else None
    if h is None:
        return 0
    for m in ("ToInt64", "ToInt32"):
        try:
            return int(getattr(h, m)())
        except Exception:
            continue
    return 0


def _win_drag():
    """让系统接管拖动：ReleaseCapture + WM_NCLBUTTONDOWN(HTCAPTION)。"""
    import ctypes
    hwnd = _hwnd()
    if not hwnd:
        return
    u = ctypes.windll.user32
    u.ReleaseCapture()
    u.SendMessageW(hwnd, 0xA1, 0x2, 0)          # WM_NCLBUTTONDOWN, HTCAPTION


# 命中测试码 → 八个缩放方向（HTLEFT/HTRIGHT/HTTOP/HTTOPLEFT/HTTOPRIGHT/
# HTBOTTOM/HTBOTTOMLEFT/HTBOTTOMRIGHT）
_HT_EDGE = {"l": 10, "r": 11, "t": 12, "tl": 13, "tr": 14,
            "b": 15, "bl": 16, "br": 17}


def _win_resize(edge):
    """手动拖边缩放：按住鼠标期间跟随光标实时改窗口矩形。

    曾经用「补 WS_THICKFRAME + WM_NCLBUTTONDOWN」让系统接管缩放，系统确实
    给了边缘热区，但 THICKFRAME 会带回一圈 7px 的非客户区边框且被 DWM 画成
    纯黑（四边都有，浅色界面下顶部最显眼）——用户不能接受，弃用。

    现在由这里自己跟随光标：热区 mousedown → 页面调 /api/ctl?do=resize，
    本函数循环采样鼠标位移并 SetWindowPos，松开左键结束。最大/最小化时忽略。
    """
    import ctypes
    import ctypes.wintypes as wt
    import time
    hwnd = _hwnd()
    edge = (edge or "").lower()
    if not hwnd or edge not in _HT_EDGE:
        return
    u = ctypes.windll.user32
    if u.IsZoomed(hwnd) or u.IsIconic(hwnd):
        return

    start = wt.POINT()
    u.GetCursorPos(ctypes.byref(start))
    r0 = wt.RECT()
    u.GetWindowRect(hwnd, ctypes.byref(r0))
    MIN_W, MIN_H = 560, 420
    SWP_NOZORDER, SWP_NOACTIVATE = 0x0004, 0x0010
    VK_LBUTTON = 0x01
    frames = 0
    while u.GetAsyncKeyState(VK_LBUTTON) & 0x8000:      # 按住左键期间
        pt = wt.POINT()
        u.GetCursorPos(ctypes.byref(pt))
        dx, dy = pt.x - start.x, pt.y - start.y
        l, t, r, b = r0.left, r0.top, r0.right, r0.bottom
        if "l" in edge:
            l = min(r0.left + dx, r0.right - MIN_W)
        if "r" in edge:
            r = max(r0.right + dx, r0.left + MIN_W)
        if "t" in edge:
            t = min(r0.top + dy, r0.bottom - MIN_H)
        if "b" in edge:
            b = max(r0.bottom + dy, r0.top + MIN_H)
        u.SetWindowPos(hwnd, 0, l, t, r - l, b - t,
                       SWP_NOZORDER | SWP_NOACTIVATE)
        frames += 1
        time.sleep(0.016)                               # ~60fps
    if frames:
        log("resize: edge=%s 手动跟随 %d 帧" % (edge, frames))


FIXED_PORT = int(os.environ.get("FYS_PORT") or 8777)   # 默认固定端口（GSI cfg / OBS 地址才稳定）


def _own_instance_info(port, timeout=1.0):
    """该端口上如果是**本软件**的另一个实例，返回它的 /api/ping 内容，否则 None。
    走 /api/ping（带 app 标识），比「端口能连上」可靠：8777 被别的东西占了不能当成自己。"""
    try:
        with urllib.request.urlopen("http://127.0.0.1:%d/api/ping" % int(port),
                                    timeout=timeout) as r:
            d = json.loads(r.read().decode("utf-8", "replace"))
        return d if isinstance(d, dict) and d.get("app") == "fys-reward" else None
    except Exception:                                          # noqa: BLE001
        return None


def _own_instance_on(port, timeout=1.0):
    return _own_instance_info(port, timeout) is not None


def _probe_port(port, timeout=0.8):
    """端口是否已被占用、占用者是不是本软件。

    返回 (in_use, own_info)：own_info 非空表示「本软件已在跑」，内容就是它的 /api/ping。
    """
    try:
        with socket.create_connection(("127.0.0.1", int(port)), timeout=timeout):
            pass
    except OSError:
        return False, None
    return True, _own_instance_info(port)


INSTANCE_FILE = os.path.join(BASE_DIR, "data", "instance.json")


def _instance_claim(port, win=None):
    """登记「我正跑在哪个端口」，供下一次启动找到我。

    光靠固定端口不够：8777 被别的程序占着时首个实例会退到随机端口，
    第二次双击再去探 8777 就找不到自己、于是又开一个。用一个 pid+port 的小文件兜住。
    """
    try:
        os.makedirs(os.path.dirname(INSTANCE_FILE), exist_ok=True)
        tmp = "%s.%d.tmp" % (INSTANCE_FILE, threading.get_ident())
        with io.open(tmp, "w", encoding="utf-8") as fh:
            json.dump({"pid": os.getpid(), "port": int(port),
                       "hwnd": _main_hwnd(win), "at": time.time()}, fh)
        os.replace(tmp, INSTANCE_FILE)
    except OSError:
        pass


def _instance_release():
    """退出时把自己的登记删掉（只删自己的，别删别人刚写的）。"""
    try:
        with io.open(INSTANCE_FILE, "r", encoding="utf-8") as fh:
            d = json.load(fh)
        if int(d.get("pid") or 0) == os.getpid():
            os.remove(INSTANCE_FILE)
    except (OSError, ValueError):
        pass


def _find_running_instance():
    """读登记文件，确认那个实例还活着（端口上确实是本软件、且 pid 对得上）。

    返回 (port, ping_info) 或 None。死进程留下的旧文件会被忽略（并顺手覆盖）。
    """
    try:
        with io.open(INSTANCE_FILE, "r", encoding="utf-8") as fh:
            d = json.load(fh)
        port = int(d.get("port") or 0)
        pid = int(d.get("pid") or 0)
    except (OSError, ValueError, TypeError):
        return None
    if port <= 0 or pid <= 0 or pid == os.getpid():
        return None
    info = _own_instance_info(port)
    if info and int(info.get("pid") or 0) == pid:
        return port, info
    return None


def _activate_existing(port, info=None):
    """双击了第二次：**不弹提示、不开新实例**，直接把已经开着的那个窗口叫到前台。

    顺序很关键：先 AllowSetForegroundWindow(前台进程 pid) 把「允许抢占前台」的
    权利交给已在运行的那个进程，再请求它 /api/ctl?do=focus（它会 restore + 置前）；
    否则 Windows 前台锁会让 SetForegroundWindow 静默失败（窗口只闪任务栏）。
    """
    pid = (info or {}).get("pid")
    hwnd = (info or {}).get("hwnd")
    u = ctypes.windll.user32
    ok = False
    # ① 本进程就是「用户刚双击起来的那个」，此时有前台权限 —— 直接操作对方窗口最可靠：
    #    还原（最小化时）+ 置顶 + 抢前台。跨进程 ShowWindow 是允许的。
    try:
        u.AllowSetForegroundWindow(int(pid) if pid else -1)     # -1 = ASFW_ANY
    except Exception:                                          # noqa: BLE001
        pass
    if hwnd:
        try:
            u.ShowWindow(hwnd, 9)          # SW_RESTORE
            u.BringWindowToTop(hwnd)
            ok = bool(u.SetForegroundWindow(hwnd))
        except Exception:                                      # noqa: BLE001
            pass
    # ② 再让已运行的那个实例自己也做一遍（它的 win.restore()/show() 能处理隐藏、任务栏等状态）
    try:
        with urllib.request.urlopen("http://127.0.0.1:%d/api/ctl?do=focus" % int(port),
                                    timeout=2.0) as r:
            d = json.loads(r.read().decode("utf-8", "replace"))
        ok = ok or bool((d or {}).get("ok"))
    except Exception as e:                                     # noqa: BLE001
        log("[服务] 请求已有实例聚焦失败：%r" % (e,))
    log("[服务] 已有实例占用 %d（pid=%s），已把它的窗口叫到前台：%s"
        % (int(port), pid, "成功" if ok else "未确认"))
    return ok


def free_port():
    s = socket.socket()
    s.bind(("127.0.0.1", 0))
    port = s.getsockname()[1]
    s.close()
    return port


def _win_state(win):
    """真实窗口状态：0 正常 / 1 最小化 / 2 最大化；读不到返回 None。
    不用自己记的标志位——窗口可能被拖到屏顶(Aero Snap)、Win+↑、双击标题栏
    等多种方式改变状态，只有读系统真实状态按钮行为才不会乱。"""
    try:
        if win is None or win.native is None:
            return None
        return int(win.native.WindowState)
    except Exception:
        return None


def _find_main_hwnd():
    """按「本进程 + 顶层 + 可见 + 标题含 云朵小铺」找主窗口句柄。

    pywebview 的 win.native 在不同环境下暴露的句柄不一定可靠（实测拿到 None），
    所以再加一条系统级兜底：EnumWindows 按 pid + 标题精确找。
    """
    from ctypes import wintypes
    u = ctypes.windll.user32
    pid = os.getpid()
    found = []

    @ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)
    def _cb(hwnd, _lp):
        wpid = wintypes.DWORD()
        u.GetWindowThreadProcessId(hwnd, ctypes.byref(wpid))
        if wpid.value != pid or not u.IsWindowVisible(hwnd):
            return True
        n = u.GetWindowTextLengthW(hwnd)
        if n <= 0:
            return True
        buf = ctypes.create_unicode_buffer(n + 1)
        u.GetWindowTextW(hwnd, buf, n + 1)
        if "云朵小铺" in buf.value:
            found.append(int(hwnd))
            return False
        return True

    try:
        u.EnumWindows(_cb, 0)
    except Exception:                                          # noqa: BLE001
        return None
    return found[0] if found else None


def _main_hwnd(win):
    """主窗口的 Win32 句柄（先问 pywebview，拿不到再系统枚举）。"""
    try:
        if win is not None and win.native is not None:
            h = win.native.Handle
            if h:
                return int(h)
    except Exception:                                          # noqa: BLE001
        pass
    return _find_main_hwnd()


def _focus_main_window(win):
    """把主窗口从最小化/后台恢复到前台。第二次双击时由已运行实例执行。

    ⚠ SetForegroundWindow 受 Windows 前台锁限制：由**第二个进程**先调
    AllowSetForegroundWindow(第一个进程 pid)，第一个进程再调才稳（见 _activate_existing）。
    """
    if win is None:
        return False
    try:
        if _win_state(win) == 1:            # 最小化 → 还原
            win.restore()
    except Exception:                                          # noqa: BLE001
        pass
    try:
        win.show()                          # 被隐藏时也显示出来
    except Exception:                                          # noqa: BLE001
        pass
    hwnd = _main_hwnd(win)
    if not hwnd:
        return False
    u = ctypes.windll.user32
    try:
        u.ShowWindow(hwnd, 9)               # SW_RESTORE
    except Exception:                                          # noqa: BLE001
        pass
    try:
        u.BringWindowToTop(hwnd)
    except Exception:                                          # noqa: BLE001
        pass
    ok = False
    try:
        ok = bool(u.SetForegroundWindow(hwnd))
    except Exception:                                          # noqa: BLE001
        pass
    return ok


def do_control(action, q=None):
    st = State
    q = q or {}
    # 注：原来这里有个 do=refresh（同步重建全量索引），会把这个请求线程挂到下载结束。
    # 前端从未调用过它（「立即同步」走的是 do=sync → 后台 _sync_worker），已删除。
    if action == "diffseen":       # 上游数据更新提醒：用户确认（横幅消失）
        try:
            State.engine.diff_mark_seen()
        except Exception:                                      # noqa: BLE001
            pass
        return {"ok": True}

    # ── CS2 GSI（游戏状态集成）：开启 = 生成 token 并写游戏 cfg；关闭 = 真卸载 ──
    if action in ("gsi_on", "gsi_off", "gsi_install", "gsi_remove"):
        # 语义统一：写配置 = 开启；卸载配置 = 关闭。否则「开关是关的、配置却写着」
        # 两边状态打架，用户根本不知道现在到底在不在接收数据。
        if action in ("gsi_on", "gsi_install"):
            gsi.set_enabled(True)
            r = gsi.cfg_install(State.port)
        else:
            gsi.set_enabled(False)
            r = gsi.cfg_remove()
        out = {"ok": bool(r.get("ok")), "result": r}
        out.update(gsi.status_payload())
        return out

    if action == "sync":
        if not State.sync["running"]:
            threading.Thread(target=_sync_worker, daemon=True).start()
        return {"ok": True, "running": True}
    if action == "dgtest":         # 回归专用：模拟「同步后索引换代」（代际 +1）
        if os.environ.get("FYS_TEST_HOOKS") != "1":
            return {"ok": False, "error": "未开放"}       # 正式运行不存在这个入口
        try:
            return {"ok": True, "dgen": State.engine.bump_data_gen()}
        except Exception:                                  # noqa: BLE001
            return {"ok": False, "error": "引擎不可用"}
    if action == "syncstatus":
        return {"ok": True, "sync": dict(State.sync)}
    # v2.14：新图封面补齐（同步后自动跑，这里给手动/回归一个入口）
    if action == "coversync":
        force = (q.get("force") or [""])[0].lower() not in ("", "0", "false", "no")
        return {"ok": True, "cover": cover_sync(force=force)}
    if action == "coverstat":
        return {"ok": True, "cover": cover_stat(force=True),
                "sync": dict(_COVER_SYNC)}
    win = st.win
    if action in ("ovsave", "ovstate", "ovresize", "ovopen", "ovclose", "ovpoll",
                  "ovtkpos", "opentxt", "opentxtloc", "opendata", "openlog",
                  "openpreview"):
        pass                       # 覆盖窗口操作与外部打开不依赖主窗口
    elif win is None:
        return {"ok": False, "error": "窗口不可用"}
    try:
        if action == "min":
            win.minimize()
            return {"ok": True}
        if action == "maxtoggle":
            if _win_state(win) == 2:
                win.restore()
            else:
                win.maximize()
            st.maximized = (_win_state(win) == 2)
            return {"ok": True, "max": st.maximized}
        if action == "state":
            return {"ok": True, "max": _win_state(win) == 2}
        if action == "focus":               # 第二次双击：把已运行的主窗口叫到前台
            return {"ok": _focus_main_window(win), "state": _win_state(win)}
        if action == "close":
            threading.Thread(target=win.destroy, daemon=True).start()
            return {"ok": True}
        if action == "drag":
            _win_drag()
            return {"ok": True}
        # 页面自绘的 8 向边缘热区：进入「拖边沿改窗口大小」。
        # 这个请求会一直挂到用户松开鼠标（SendMessage 进入系统模态循环），
        # 前端 fire-and-forget 即可，别等它的返回。
        if action == "resize":
            _win_resize((q.get("edge") or [""])[0])
            return {"ok": True}
        # ── 屏幕覆盖 ──
        if action == "ovsave":
            try:
                inc = json.loads((q.get("cfg") or ["{}"])[0])
            except Exception as e:
                return {"ok": False, "error": "cfg 解析失败: %r" % e}
            cfg = json.loads(json.dumps(ensure_ovcfg()))
            old_mode = cfg.get("mode")
            old_live = bool(cfg.get("livetxt"))
            old_layout = cfg.get("layout")
            old_skin = bool(cfg.get("skin"))
            # 不信任前端：类型/范围就地清洗。坏值（size="abc"、bg=5）会让覆盖窗
            # 渲染线程每帧抛异常 → 小窗白板，而且只在日志里留一行 traceback
            if "color" in inc and re.fullmatch(r"#[0-9a-fA-F]{6}", str(inc.get("color") or "")):
                cfg["color"] = inc["color"]
            if "size" in inc:
                try:                          # 与页面滑杆一致：16~72 步进 1
                    cfg["size"] = max(8, min(72, int(float(inc["size"]))))
                except (TypeError, ValueError):
                    pass
            if "bg" in inc:
                try:                          # 与页面滑杆一致：0~0.95
                    cfg["bg"] = max(0.0, min(0.95, float(inc["bg"])))
                except (TypeError, ValueError):
                    pass
            if inc.get("mode") in ("frameless", "tkinter"):
                cfg["mode"] = inc["mode"]
            if inc.get("layout") in ("card", "compact", "iconic", "skin"):
                cfg["layout"] = inc["layout"]
            if "skin" in inc:                # 只认白名单文件名或空（不信任前端路径）
                s = str(inc.get("skin") or "")
                cfg["skin"] = s if s in ("", OV_SKIN_NAME) else cfg.get("skin", "")
            if "skin_op" in inc:             # 底图透明度滑杆：20~95，越大底图越透亮
                try:
                    cfg["skin_op"] = max(20, min(95, int(float(inc["skin_op"]))))
                except (TypeError, ValueError):
                    pass
            if isinstance(inc.get("skin_crop"), dict):
                # 取景框走 _skin_crop_norm 统一清洗（越界夹回而不是拒绝），
                # 保证存进去的一定是合法框；非法（比如框没了）就保持原样
                _nc = _skin_crop_norm(inc["skin_crop"])
                if _nc:
                    cfg["skin_crop"] = _nc
            for k in ("livetxt", "ov_ct"):
                if k in inc:
                    cfg[k] = bool(inc[k])
            if isinstance(inc.get("show"), dict):
                for k, _d, _n in OV_FIELDS:
                    if k in inc["show"]:
                        cfg["show"][k] = bool(inc["show"][k])
            # rev 递增：小窗拿它判断配置有没有真的变（没变就跳过整棵 DOM 重建）
            try:
                cfg["rev"] = int(cfg.get("rev") or 0) + 1
            except (TypeError, ValueError):
                cfg["rev"] = 1
            save_ovcfg(cfg)
            if old_live and not cfg.get("livetxt"):
                livetxt_remove("own")          # 关掉开关就清掉 txt，避免 OBS 读旧数据
            # ── 重启判定（v2.3 优化 6）：只有「建窗参数」变了才重建小窗 ──
            # 两种模式的窗口都会自己重读配置：frameless 走 loadCfg(2s)、
            # tkinter 走 cfg_tick(2s)，所以颜色/字号/背景深度/底图透明度/显示内容
            # 全是热更，鼠标穿透也是热切（优化 7）——勾一项就重启反而会每秒闪。
            structural = []
            if old_mode != cfg.get("mode"):
                structural.append("mode")
            if old_layout != cfg.get("layout"):
                structural.append("layout")
            if old_skin != bool(cfg.get("skin")):
                structural.append("skin")
            if structural and ov_alive():
                ov_restart(structural_changed=True)
            return {"ok": True, "cfg": cfg, "restart": bool(structural)}
        if action == "ovtkpos":            # tkinter 覆盖窗拖动后回存位置
            if State.ov_nosave:            # 换预设落点导致的重启：忽略这次的旧坐标
                return {"ok": True, "skipped": True}
            try:
                x = int((q.get("x") or ["0"])[0])
                y = int((q.get("y") or ["0"])[0])
                cfg = ensure_ovcfg()
                cfg["x"], cfg["y"] = x, y
                save_ovcfg(cfg)
            except (TypeError, ValueError):
                pass
            return {"ok": True}
        if action == "ovopen":
            return ov_open()
        if action == "ovclose":
            return ov_close()
        if action == "ovskinclear":        # 清除自定义底图（布局 D 回到默认紫底）
            return ovskin_clear()
        if action == "ovstate":
            return {"ok": True, "on": ov_alive()}
        if action == "ovresize":           # 只记录目标尺寸，由覆盖子进程自己取
            try:
                w = int((q.get("w") or ["0"])[0])
                h = int((q.get("h") or ["0"])[0])
                if w > 0 and h > 0:
                    State.ovsize = (max(120, w), max(48, h))
            except (TypeError, ValueError):
                pass
            return {"ok": True}
        if action == "ovpoll":             # 覆盖子进程每 0.3s 来问：尺寸变了/要退出吗
            w, h = State.ovsize or (None, None)
            _c = ensure_ovcfg()
            return {"ok": True, "close": bool(State.ovclose_flag), "w": w, "h": h,
                    "nosave": bool(State.ov_nosave),
                    "ct": bool(_c.get("ov_ct")), "rev": int(_c.get("rev") or 0)}
        if action == "opentxt":            # 打开直播文本 txt（没生成过就打开所在文件夹）
            p = livetxt_path()
            try:
                if os.path.exists(p):
                    os.startfile(p)        # noqa: S606
                else:
                    os.makedirs(os.path.dirname(p), exist_ok=True)
                    os.startfile(os.path.dirname(p))  # noqa: S606
                return {"ok": True}
            except Exception as e:                         # noqa: BLE001
                return {"ok": False, "error": repr(e)}
        if action == "opentxtloc":         # 在资源管理器中定位直播文本 txt
            p = livetxt_path()
            try:
                if not os.path.exists(p):
                    os.makedirs(os.path.dirname(p), exist_ok=True)
                    open(p, "a", encoding="utf-8-sig").close()   # 先建空文件才能定位
                subprocess.Popen(["explorer", "/select," + p])       # noqa: S606
                return {"ok": True}
            except Exception as e:                         # noqa: BLE001
                return {"ok": False, "error": repr(e)}
        # ── 设置页「关于」卡：打开数据目录 / 运行日志 ──
        if action == "opendata":
            try:
                d = os.path.join(BASE_DIR, "data")
                os.makedirs(d, exist_ok=True)
                os.startfile(d)            # noqa: S606
                return {"ok": True, "path": d}
            except Exception as e:                         # noqa: BLE001
                return {"ok": False, "error": repr(e)}
        if action == "openlog":
            try:
                if os.path.exists(LOG_PATH):
                    subprocess.Popen(["explorer", "/select," + LOG_PATH])  # noqa: S606
                else:
                    os.makedirs(os.path.dirname(LOG_PATH), exist_ok=True)
                    open(LOG_PATH, "a", encoding="utf-8").close()
                    os.startfile(os.path.dirname(LOG_PATH))                # noqa: S606
                return {"ok": True, "path": LOG_PATH}
            except Exception as e:                         # noqa: BLE001
                return {"ok": False, "error": repr(e)}
        # ── 地图实体预览备用出口：独立窗口（内嵌视图在 view-pre，这里给「🪟 独立窗口」按钮）──
        if action == "openpreview":
            return pv_open((q.get("map") or [""])[0])
    except Exception as e:
        return {"ok": False, "error": repr(e)}
    return {"ok": False, "error": "未知操作"}


# ─── /api JSON 接口路由表（v2.14 美化⑫）────────────────────────────
# 以前是 do_GET 里 25+ 个 elif 一条长链，加接口要摸清整条链的 body/ct 流转；
# 现在每个接口一个小函数、返回 dict 即可，do_GET 分发层统一 json 编码。
# 各接口原来的 try/except 与失败兜底形状原样搬进函数 —— 前端依赖的返回
# 结构不变；分发层不再统一兜错，避免掩盖各接口期待的返回形状。
# 复杂的非 JSON 路由（/ /overlay /terr/ /cover/ /api/ovskin…）仍留在 do_GET。

def _api_prefs(q):
    """界面偏好读写。

    ⚠ 写路径必须「读-改-写」原子：ThreadingHTTPServer 下同一毫秒到达的两个
    set 请求会各自读到同一份旧文件，后写的把先写的键整个覆盖掉。
    实测「↺ 恢复默认外观」一次点击连发 theme/bg/sticker 三个请求
    （applyTheme/applyBG/applySticker），bg 每次都丢，下次启动背景回滚。
    用独立 RLock 串行化（save_uiprefs 内部另有 _CFG_LOCK，不能直接嵌套）。"""
    prefs = load_uiprefs()
    if "set" in q:
        k = (q.get("set") or [""])[0]
        try:
            v = json.loads((q.get("val") or ["null"])[0])
        except ValueError:
            v = None
        if k:
            with _PREFS_LOCK:
                prefs = load_uiprefs()          # 锁内重读：拿到的必须是别人刚写完的版本
                prefs[k] = v
                save_uiprefs(prefs)
    return {"ok": True, "prefs": prefs}


def _api_update_check(q):
    return update_check(force=("force" in q))


def _api_update_apply(q):
    return update_apply()


def _api_update_progress(q):
    return {"ok": True, **_UPD_PROG}


def _api_preview_progress(q):
    return {"ok": True, **_PV_PROG}


def _api_terr_info(q):
    wf = (q.get("wf") or [""])[0]
    out = {"ok": True, **terr_stat(force=("force" in q))}
    if re.fullmatch(r"[0-9]{1,20}", wf or ""):
        out["wf"] = wf
        out["cached"] = os.path.exists(
            os.path.join(terr_dir() or BASE_DIR, wf + ".bin"))
    return out


def _api_terr_clear(q):
    return terr_clear()


def _api_preview(q):
    return preview_info()


def _api_preview_fetch(q):
    fp, err = preview_fetch()
    return {"ok": bool(fp), "err": err,
            "size": (os.path.getsize(fp) if fp else 0)}


def _api_ovcfg(q):
    return {"ok": True, "cfg": ensure_ovcfg(),
            "fields": [list(f) for f in OV_FIELDS],
            "livetxt_path": livetxt_path()}


def _api_ovpoll(q):
    return do_control("ovpoll")


def _api_status(q):
    try:
        data = State.engine.resolve()
    except Exception as e:
        data = {"ok": False, "state": "error", "state_text": "内部错误",
                "error": repr(e), "stages": [], "raw": ""}
    if isinstance(data, dict):
        st2 = _win_state(State.win)
        data["winmax"] = None if st2 is None else (st2 == 2)
        try:
            m = State.engine.STATE.get("meta") or {}
            data["datainfo"] = {"built_at": m.get("built_at_str"),
                                "maps": m.get("maps"), "stages": m.get("stages")}
        except Exception:                                      # noqa: BLE001
            data["datainfo"] = None
        try:
            # 数据代际：前端发现它变了就作废地图库缓存（同步完成后
            # 不重启也能看到新配置，见 ui_page.dgInvalidate）
            data["dgen"] = State.engine.data_gen()
        except Exception:                                      # noqa: BLE001
            data["dgen"] = 0
        data["sync"] = dict(State.sync)
        try:
            data["upddiff"] = State.engine.diff_summary()
        except Exception:                                      # noqa: BLE001
            data["upddiff"] = None
        data["ovon"] = ov_alive()
        # 「关于」卡刻意不塞进这里：about_payload() 要跑 preview_info()
        # （对云端发 HEAD，最长 6s）与 terr_stat()，而本接口每秒被前端轮询。
        # 以前每轮都会触发一次跨境 HEAD，断网时直接把请求线程挂住 6 秒。
        # 现由设置页进页时单独拉 /api/about。
        livetxt_tick(data)          # 直播文本 txt（勾选后才真正写盘）
    return data


def _api_ping(q):
    """单实例探测：回应用标识 / pid / 主窗口句柄（第二个实例据此把窗口叫到前台）。"""
    return {"app": "fys-reward", "ver": APP_VER, "pid": os.getpid(),
            "hwnd": _main_hwnd(State.win)}


def _api_gsi(q):
    """GSI 状态卡（设置页/战绩页用；不塞进每秒轮询的 /api/status 大对象）。"""
    try:
        d = gsi.status_payload()
        d["listen_port"] = State.port
        return d
    except Exception as e:                                     # noqa: BLE001
        return {"ok": False, "error": repr(e)}


def _api_matches(q):
    """对局战绩（含该图该关的通关云点/龙晶与伤害转化比联动列）。"""
    try:
        return {"ok": True, "rows": gsi.matches(60), "summary": gsi.summary()}
    except Exception as e:                                     # noqa: BLE001
        return {"ok": False, "rows": [], "error": repr(e)}


def _api_about(q):
    # 设置页「关于」卡专用，按需拉取（不进每秒轮询）
    return about_payload()


def _api_mapnames(q):
    # 地图译名表：地图实体预览页用它覆盖「壳里构建时的译名快照」，
    # 于是服务器上补译名后预览页即刻生效，不用重下 14MB 的预览壳。
    try:
        import mapnames as _mn
        _names = _mn.effective_names()
    except Exception as _e:                                    # noqa: BLE001
        log("mapnames: /api/mapnames 失败 %r" % (_e,))
        _names = {}
    return {"ok": True, "n": len(_names), "names": _names}


def _api_ctl(q):
    return do_control((q.get("do") or [""])[0], q)


def _api_servers(q):
    try:
        return State.engine.servers_payload()
    except Exception as e:                                     # noqa: BLE001
        return {"rows": [], "error": repr(e)}


def _api_maplib(q):
    try:
        # 首启竞态：索引在后台线程加载，赶在它完成前应答会返回空表，
        # 前端又会把「共 0 张」缓存住 → 地图库显示为 0。与 /api/mapparams
        # /api/updlog 一样先等就绪（ThreadingHTTPServer，短期等待安全）。
        State.engine.wait_state()
        return {"ok": True, "maps": maplib_records(), "meta": maplib_meta()}
    except Exception as e:                                     # noqa: BLE001
        return {"ok": False, "maps": [], "error": repr(e)}


def _api_mapparams(q):
    try:
        State.engine.wait_state()      # 首启竞态：等后台 load_state 就绪
        return State.engine.map_params_payload((q.get("f") or [""])[0])
    except Exception as e:                                     # noqa: BLE001
        return {"ok": False, "error": repr(e)}


def _api_mapdiff(q):
    try:
        State.engine.wait_state()      # 首启竞态：等后台 load_state 就绪
        return State.engine.map_diff_payload((q.get("f") or [""])[0])
    except Exception as e:                                     # noqa: BLE001
        return {"ok": False, "error": repr(e)}


def _api_updlog(q):
    try:
        State.engine.wait_state()      # 同上
        return State.engine.updlog_payload()
    except Exception as e:                                     # noqa: BLE001
        return {"ok": False, "total": 0, "entries": [], "error": repr(e)}


def _api_rewards(q):
    try:
        return State.engine.rewards_payload((q.get("map") or [""])[0])
    except Exception as e:                                     # noqa: BLE001
        return {"ok": False, "stages": [], "error": repr(e)}


def _api_upddiff(q):
    try:
        return State.engine.diff_payload()
    except Exception as e:                                     # noqa: BLE001
        return {"counts": {"total": 0}, "groups": {}, "error": repr(e)}


_API_ROUTES = {
    "/api/ping": _api_ping,
    "/api/prefs": _api_prefs,
    "/api/gsi": _api_gsi,
    "/api/matches": _api_matches,
    "/api/bgimg": lambda q: bgimg_get(),
    "/api/update/check": _api_update_check,
    "/api/update/apply": _api_update_apply,
    "/api/update/progress": _api_update_progress,
    "/api/preview/progress": _api_preview_progress,
    "/api/terr/info": _api_terr_info,
    "/api/terr/clear": _api_terr_clear,
    "/api/preview": _api_preview,
    "/api/preview/fetch": _api_preview_fetch,
    "/api/ovcfg": _api_ovcfg,
    "/api/ovpoll": _api_ovpoll,
    "/api/status": _api_status,
    "/api/about": _api_about,
    "/api/mapnames": _api_mapnames,
    "/api/ctl": _api_ctl,
    "/api/servers": _api_servers,
    "/api/maplib": _api_maplib,
    "/api/mapparams": _api_mapparams,
    "/api/mapdiff": _api_mapdiff,
    "/api/updlog": _api_updlog,
    "/api/rewards": _api_rewards,
    "/api/upddiff": _api_upddiff,
}


def make_handler():
    from http.server import BaseHTTPRequestHandler

    class H(BaseHTTPRequestHandler):
        # 必须 HTTP/1.1：Chromium 对 HTTP/1.0 的响应**一律不入 HTTP 缓存**
        # （实测：同样的 Cache-Control: no-cache + ETag，HTTP/1.0 下第二次仍全量 200，
        #  HTTP/1.1 下第二次直接 304）。这也是「每次进实体预览都重下 14MB」的根因。
        # 换 1.1 后每条响应都必须有 Content-Length，否则 keep-alive 会挂住客户端。
        protocol_version = "HTTP/1.1"

        def log_message(self, *a):
            pass

        def _host_ok(self):
            """服务只听 127.0.0.1 且不带任何凭据，但仍要防两类浏览器攻击：
            ① 恶意网页对 http://127.0.0.1:port 发跨站 GET（虽然读不到响应，
               但 /api/ctl、/api/prefs 这类带副作用的请求会被照样执行）；
            ② DNS rebinding（把恶意域名解析到 127.0.0.1 绕过同源策略）。
            校验 Host 必须是本机回环；带了 Origin 的请求，其主机也必须是本机。
            同源 GET 不会带 Origin，所以正常界面不受影响。"""
            def _loop(h):
                h = (h or "").strip().lower()
                h = h.rsplit(":", 1)[0] if h.count(":") == 1 else h.lstrip("[").split("]")[0]
                return h in ("127.0.0.1", "localhost", "::1")
            if not _loop(self.headers.get("Host")):
                return False
            origin = self.headers.get("Origin")
            if origin:
                try:
                    oh = urllib.parse.urlsplit(origin).hostname or ""
                except ValueError:
                    return False
                if oh.lower() not in ("127.0.0.1", "localhost", "::1"):
                    return False
            return True

        def do_GET(self):
            if not self._host_ok():
                self.send_response(403)
                self.send_header("Content-Length", "0")
                self.end_headers()
                return
            p = urllib.parse.urlparse(self.path).path
            q = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            etag = None                 # 只有大静态资源会给 ETag（动态接口一律 no-store）
            cctl = "no-store"
            lm_hdr = None
            if p in ("/", "/index.html"):
                body, ct = HTML.encode("utf-8"), "text/html; charset=utf-8"
                etag, cctl = root_etag(), "no-cache"
            elif p in ("/static/app.css", "/static/app.js"):
                # 样式表与主脚本（v2.14 从主页 HTML 拆出来）：主页从 862KB 降到 ~110KB，
                # 静态件单独走 ETag/304；?v= 与当前内容哈希一致时才给长缓存
                # （升级后 URL 必变，不会出现旧样式配新 DOM）。
                _av = ui_page.asset_ver(APP_VER)
                if p.endswith(".css"):
                    body = ui_page.css_asset(APP_VER).encode("utf-8")
                    ct = "text/css; charset=utf-8"
                else:
                    body = ui_page.js_asset(APP_VER).encode("utf-8")
                    ct = "application/javascript; charset=utf-8"
                etag = '"as-%s"' % _av
                cctl = ("public, max-age=31536000, immutable"
                        if (q.get("v") or [""])[0] == _av else "no-cache")
            elif p == "/overlay":
                body, ct = ui_page.OVERLAY_HTML.encode("utf-8"), "text/html; charset=utf-8"
            elif p in ("/preview3d", "/preview"):
                # 地图实体预览（3D）：整页交给内置的静态文件，?map= / ?embed= / ?th= 由页内脚本处理
                try:
                    body = preview_bytes()
                    # 页码重：14MB 每次重传太浪费，用「长度+mtime」当 ETag
                    _mt = int(_PREVIEW_CACHE.get("mtime") or 0)
                    etag = '"pv-%d-%d"' % (len(body), _mt)
                    lm_hdr = email.utils.formatdate(_mt, usegmt=True)
                    cctl = "no-cache"
                except Exception:                              # noqa: BLE001
                    body = PREVIEW_MISSING_HTML.encode("utf-8")
                ct = "text/html; charset=utf-8"
            elif p.startswith("/terr/"):
                # 预览页的地形分包：terr/<工坊ID>.bin（原始 gz，fetch 拉取）。
                # v1.6 起：本地缓存命中直接返回；未命中则由 terr_fetch 从云端按需
                # 下载并落盘（等于给前端做了一个透明的"本地缓存代理"，页内代码不改）。
                name = os.path.basename(p[len("/terr/"):])
                if not re.fullmatch(r"[A-Za-z0-9_.\-]{1,64}\.(?:bin|js)", name):
                    self.send_response(400)
                    self.send_header("Content-Length", "0")
                    self.end_headers()
                    return
                fp = os.path.join(terr_dir() or BASE_DIR, name)
                body = None
                if os.path.exists(fp):
                    try:
                        with open(fp, "rb") as fh:
                            body = fh.read()
                        _mt = int(os.path.getmtime(fp))
                        etag = '"t-%d-%d"' % (len(body), _mt)
                        lm_hdr = email.utils.formatdate(_mt, usegmt=True)
                        cctl = "no-cache"
                    except OSError:
                        body = None
                if body is None:
                    # .js 是旧版 file:// 兜底格式，服务器只放 .bin，不回源
                    data, err = ((None, "net") if name.endswith(".js")
                                 else terr_fetch(name))
                    if data is None:
                        # 404=远端也没有这张图（别重试）；502=下载失败（断网/超时，可重试）。
                        # 带 JSON body：preview3d.html 只能看到状态码，拿不到原因就没法
                        # 区分「官方没收录这张图」和「网络抽风」，只能都提示「下载失败」。
                        # 404 = 这张图确实没有（本机没有、托管也没有，等下次更新）
                        # 502 = 本该有但这次拿不到（断网/超时/目录不可写）→ 可重试
                        _miss = (err == "miss")
                        _msg = ("地形未收录（这张图还没有地形分包，等版本更新）" if _miss else
                                "地形下载源未配置（请更新到带下载地址的版本）" if err == "nocdn" else
                                "地形目录不可写（检查安装目录权限）" if err == "nodir" else
                                "地形下载失败（检查网络后重开该图）")
                        _why = {"ok": False, "err": err or "net", "msg": _msg}
                        _b = json.dumps(_why, ensure_ascii=False).encode("utf-8")
                        self.send_response(404 if _miss else 502)
                        self.send_header("Content-Type", "application/json; charset=utf-8")
                        self.send_header("Content-Length", str(len(_b)))
                        self.end_headers()
                        self.wfile.write(_b)
                        return
                    body = data
                    etag = None             # 现取的分包先不带 ETag，下次命中磁盘再走 304 分支
                    cctl = "no-cache"
                ct = ("application/octet-stream" if name.endswith(".bin")
                      else "text/javascript; charset=utf-8")
            elif p.startswith("/cover/"):
                # 地图封面（v2.3）：cover\ 下的 <地图名>.jpg。由 _build_covers.py 从官方
                # 图床 resx.fyscs.cn/mapimgs/ 抓取（统一 320x180）。
                # 取图顺序 = exe 旁的 cover\ → exe 内置副本（见 cover_dirs()）：
                # 一键更新只换 exe，老用户没有 exe 旁那份，靠内置副本兜住。
                # 抓不到的图两处都没有，前端背景会静默回退到默认底纹。
                name = os.path.basename(p[len("/cover/"):])
                if not re.fullmatch(r"[a-z0-9_.\-]{1,80}\.jpg", name):
                    self.send_response(400)
                    self.send_header("Content-Length", "0")
                    self.end_headers()
                    return
                fp = find_cover(name)
                if not fp:
                    fp = cover_fetch(name)   # 纯本地查找（v2.14 起），没有返回 None
                if not fp:
                    # v2.14：本地没有就回 404（毫秒级，不拖慢首屏），同时丢给封面补齐
                    # 线程去官方图床取一张 —— 下个请求 / 下次渲染就有了。
                    # 并发几百个 <img> 也只会有一次真正在跑（cover_sync 带 running 锁）。
                    try:
                        cover_sync(names=[name[:-4]])
                    except Exception:                          # noqa: BLE001
                        pass
                    self.send_response(404)
                    # no-store：否则 WebView 会把 404 缓存住，封面补好了也刷不出来
                    self.send_header("Cache-Control", "no-store")
                    self.send_header("Content-Length", "0")
                    self.end_headers()
                    return
                try:
                    with open(fp, "rb") as fh:
                        body = fh.read()
                    _mt = int(os.path.getmtime(fp))
                    etag = '"cv-%d-%d"' % (len(body), _mt)
                    cctl = "no-cache"
                except OSError:
                    body = b""
                if not body:
                    self.send_response(404)
                    self.send_header("Content-Length", "0")
                    self.end_headers()
                    return
                ct = "image/jpeg"
            elif p.startswith("/skin/"):
                # 覆盖窗自定义底图：data\overlay_skin.png（白名单文件名，不存在回 404）
                name = os.path.basename(p[len("/skin/"):])
                # 两个白名单名：成品底图 + 用户上传的原图（取景框要在原图上框，
                # 用成品去框会二次裁剪、越裁越小）
                if name == OV_SKIN_ORIG:
                    fp = _ovskin_orig_path()
                elif name == OV_SKIN_NAME:
                    fp = _ovskin_path()
                else:
                    self.send_response(404)
                    self.send_header("Content-Length", "0")
                    self.end_headers()
                    return
                # ⚠ 不能在这里再覆盖成 _ovskin_path()：取景框要框的是**原图**，
                # 服务成成品的话就是拿裁剪结果二次取景、越裁越小（2026-09-28 修）
                body = b""
                if os.path.exists(fp):
                    try:
                        with open(fp, "rb") as fh:
                            body = fh.read()
                        _mt = int(os.path.getmtime(fp))
                        etag = '"sk-%d-%d"' % (len(body), _mt)
                        cctl = "no-cache"
                    except OSError:
                        body = b""
                if not body:
                    self.send_response(404)
                    self.send_header("Content-Length", "0")
                    self.end_headers()
                    return
                ct = "image/png"
            elif p in _API_ROUTES:         # 纯 JSON 接口统一表驱动（v2.14 美化⑫）：
                # 各处理函数自带 try/except 与失败兜底形状（与重构前逐字一致），
                # 分发层只管编码；加新接口 = 写一个 _api_xxx + 在 _API_ROUTES 登记一行。
                body = json.dumps(_API_ROUTES[p](q), ensure_ascii=False).encode("utf-8")
                ct = "application/json; charset=utf-8"
            else:
                self.send_response(404)
                self.send_header("Content-Length", "0")   # HTTP/1.1 keep-alive 必须有长度
                self.end_headers()
                return
            # 静态资源带 ETag：浏览器再进同一页时回 304（不带 body）省掉重传
            if etag and (self.headers.get("If-None-Match") or "").strip() == etag:
                self.send_response(304)
                self.send_header("ETag", etag)
                self.send_header("Cache-Control", cctl)
                if lm_hdr:
                    self.send_header("Last-Modified", lm_hdr)
                self.end_headers()
                return
            self.send_response(200)
            self.send_header("Content-Type", ct)
            # ④ 大响应 gzip（v2.15 性能④）：客户端声明支持 gzip 且 body ≥ 32KB 才压。
            #   地图索引/参数缓存这类 JSON 是 200KB~1MB 级的重复文本，压缩比 ~8×，
            #   本机回环虽然快，冷启动解析 + 传输仍省一大截；小响应不值得花 CPU。
            #   注意在算 Content-Length 之前替换 body；ETag 是内容代际不受影响。
            if ("gzip" in (self.headers.get("Accept-Encoding") or "").lower()
                    and len(body) >= 32768):
                body = gzip.compress(body, 6)
                self.send_header("Content-Encoding", "gzip")
            self.send_header("Vary", "Accept-Encoding")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", cctl)
            if etag:
                self.send_header("ETag", etag)
            if lm_hdr:
                self.send_header("Last-Modified", lm_hdr)
            self.end_headers()
            self.wfile.write(body)

        def do_POST(self):
            """两件事：覆盖窗自定义底图上传（JSON，≤5MB）与 CS2 GSI 推送（/gsi，≤256KB）。"""
            p = urllib.parse.urlparse(self.path).path
            # GSI 推送不做 Host 头校验：CS2 的 HTTP 客户端不保证带 Host，
            # 而本服务只监听 127.0.0.1（连接天然来自本机），再加 token 足够。
            if p != "/gsi" and not self._host_ok():
                self.send_response(403)
                self.send_header("Content-Length", "0")
                self.end_headers()
                return
            if p == "/gsi":
                # CS2 按 cfg 里的 uri 往这里 POST 完整状态快照（变化即推 + 心跳）。
                # 只认本机回环 + 配置里的 auth token；不写响应体（游戏只看状态码）。
                try:
                    n = int(self.headers.get("Content-Length") or 0)
                except ValueError:
                    n = 0
                if n <= 0 or n > 256 * 1024:
                    self.send_response(413)
                    self.send_header("Content-Length", "0")
                    self.end_headers()
                    return
                try:
                    payload = json.loads(self.rfile.read(n).decode("utf-8", "replace"))
                except Exception:                              # noqa: BLE001
                    self.send_response(400)
                    self.send_header("Content-Length", "0")
                    self.end_headers()
                    return
                r = gsi.handle(payload, expect_token=gsi.token())
                try:
                    _n = gsi.received()
                    if _n == 1 or _n % 500 == 0:
                        log("[GSI] 收到第 %d 条推送（%s）"
                            % (_n, (r.get("msg") or "")[:40]))
                except Exception:                          # noqa: BLE001
                    pass
                self.send_response(200 if r.get("ok") else 403)
                self.send_header("Content-Length", "0")
                self.end_headers()
                return
            if p not in ("/api/ovskin", "/api/ovskincrop", "/api/bgimg"):
                self.send_response(404)
                self.send_header("Content-Length", "0")
                self.end_headers()
                return
            try:
                n = int(self.headers.get("Content-Length") or 0)
            except ValueError:
                n = 0
            if n <= 0 or n > 5 * 1024 * 1024:
                self._json_reply({"ok": False, "error": "请求体需在 1B ~ 5MB"})
                return
            try:
                inc = json.loads(self.rfile.read(n).decode("utf-8"))
            except Exception as e:                             # noqa: BLE001
                self._json_reply({"ok": False, "error": "JSON 解析失败: %r" % e})
                return
            if p == "/api/ovskincrop":
                self._json_reply(ovskin_crop((inc or {}).get("crop")))
            elif p == "/api/bgimg":
                self._json_reply(bgimg_upload((inc or {}).get("uri")))
            else:
                self._json_reply(ovskin_upload((inc or {}).get("data")))

        def _json_reply(self, obj):
            body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(body)

    return H


def start_http_server(port, tries=6):
    """绑定本机端口。

    固定端口优先（默认 8777）：GSI 配置、OBS/浏览器地址才不会每次变。
    · 端口被**本软件的另一个实例**占着 → 弹一句「已经在运行」，正常退出；
    · 被**别的程序**占着 → 退回随机端口继续跑（能启动比端口好看重要），日志写明；
    · 随机也绑不上才抛错。
    """
    from http.server import ThreadingHTTPServer
    # ⚠ Windows 的 SO_REUSEADDR 语义是「允许绑定已占用的端口」，
    #   ThreadingHTTPServer 默认开着它 —— 直接 bind 根本不会失败，
    #   第二个实例会跟第一个抢同一个端口（实测）。所以必须在**绑定前**探测：
    #   先连一下这个端口，连得上再问一句「是不是本软件」。
    in_use, info = _probe_port(port)
    if info:
        _activate_existing(port, info)
        return None
    first_port = 0 if in_use else port
    if in_use:
        log("[服务] 固定端口 %d 被其他程序占用 → 改用随机端口" % port)
    last_err = None
    for i in range(tries):
        try:
            srv = ThreadingHTTPServer(("127.0.0.1", first_port if i == 0 else 0),
                                      make_handler())
        except OSError as e:
            last_err = e
            log("[服务] 端口 %s 绑定失败（%r），改用随机端口重试" % (port, e))
            time.sleep(0.15)
            continue
        State.port = srv.server_address[1]
        State.url = "http://127.0.0.1:%d/" % State.port
        _instance_claim(State.port, State.win)
        atexit.register(_instance_release)
        if i > 0:                  # 固定端口没绑上、退到随机端口：记一笔，设置页能看到
            State.port_note = "固定端口 %d 被其他程序占用，已改用 %d" % (port, State.port)
            log("[服务] 已改用随机端口 %d（固定端口 %d 被别的程序占着）"
                % (State.port, port))
        threading.Thread(target=srv.serve_forever, daemon=True).start()
        return srv
    raise last_err


def find_edge():
    for p in (r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe",
              r"C:\Program Files\Microsoft\Edge\Application\msedge.exe"):
        if os.path.exists(p):
            return p
    return None


def run_edge_app(url):
    """兜底：用 Edge 应用模式开一个无浏览器边框的独立窗口。"""
    edge = find_edge()
    if not edge:
        return False
    prof = os.path.join(BASE_DIR, "data", "_edgeprofile")
    log("[兜底] Edge 应用模式窗口：%s" % url)
    try:
        proc = subprocess.Popen([
            edge, "--app=" + url,
            "--window-size=%d,%d" % (WIN_W, WIN_H),
            "--user-data-dir=" + prof,
            "--no-first-run", "--no-default-browser-check",
        ])
        proc.wait()
        return True
    except Exception as e:
        log("[!] Edge 窗口启动失败：%s" % e)
        return False


def run_browser(url):
    """最后兜底：默认浏览器。"""
    log("[兜底] 浏览器模式：%s" % url)
    threading.Timer(0.8, lambda: webbrowser.open(url)).start()
    try:
        while True:
            time.sleep(3600)
    except KeyboardInterrupt:
        pass


# ══════════════════════════ 启动 ══════════════════════════
def cleanup_stale_files():
    """启动时清扫 data/ 里的崩溃残留（建议 01）。
    - *.tmp：写盘用「tmp + os.replace」原子替换，进程被杀时会留下孤儿 tmp；
      mtime 超过 1 小时的一律删（活进程的 tmp 存活不会超过一次写盘）。
    - *.bak_*：旧版手动备份格式，每个前缀只留最新一份（历史遗留約 300KB+）。"""
    d = os.path.join(BASE_DIR, "data")
    if not os.path.isdir(d):
        return
    now = time.time()
    try:
        baks = {}
        for f in os.listdir(d):
            fp = os.path.join(d, f)
            if not os.path.isfile(fp):
                continue
            if f.endswith(".tmp"):
                try:
                    if now - os.path.getmtime(fp) > 3600:
                        os.remove(fp)
                        log("cleanup: 清掉崩溃残留 %s" % f)
                except OSError:
                    pass
            elif ".bak_" in f:
                stem = f[:f.index(".bak_")]
                try:
                    baks.setdefault(stem, []).append(
                        (os.path.getmtime(fp), fp))
                except OSError:
                    pass
        for stem, items in baks.items():
            if len(items) <= 1:
                continue
            items.sort()                    # 旧的在前
            for _m, fp in items[:-1]:       # 只留最新一份
                try:
                    os.remove(fp)
                    log("cleanup: 轮转旧备份 %s" % os.path.basename(fp))
                except OSError:
                    pass
    except OSError:
        pass                                # 扫不动就算了，不影响启动


def main():
    args = sys.argv[1:]
    if "--overlay" in args:            # 覆盖小窗子进程模式，不进主流程
        return run_overlay_child()
    if "--overlay-tk" in args:         # 原生分层透明覆盖（逐像素 alpha）
        return run_overlay_tk_child()
    if "--preview" in args:            # 地图实体预览子进程模式，不进主流程
        return run_preview_child()
    force_browser = "--browser" in args
    port = FIXED_PORT
    if "--port" in args:
        try:
            port = int(args[args.index("--port") + 1])
        except (IndexError, ValueError):
            pass
    # 单实例预检（放在加载引擎之前）：双击第二次立刻退出，不用白等十秒初始化
    try:
        hit = _find_running_instance()
        if hit:
            _activate_existing(hit[0], hit[1])
            return 0
        _in_use, _info = _probe_port(port) if port else (False, None)
        if _info:
            _activate_existing(port, _info)
            return 0
    except Exception:                                          # noqa: BLE001
        pass
    win_w, win_h = WIN_W, WIN_H
    if "--size" in args:
        try:
            w, h = args[args.index("--size") + 1].lower().split("x")
            win_w, win_h = int(w), int(h)
        except (IndexError, ValueError):
            pass

    log("=" * 46)
    log("启动 %s" % APP_TITLE)
    log("frozen=%s  exe_dir=%s  args=%s" % (getattr(sys, "frozen", False), BASE_DIR, args))
    cleanup_stale_files()                  # 崩溃残留 tmp / 旧版多份 bak

    import reward_server as engine
    State.engine = engine
    log("step: 已导入引擎，索引加载与服务器探测转后台（首屏优先，就绪后自动补上）")

    def _boot_load():
        # 服务器看板缓存不依赖索引，先拉起 watcher（云端 status.json 一秒内就有
        # 数据）——否则窗口先开、页面首次 /api/servers 会拿到空清单，要干等
        # 下一轮 15 秒轮询才补上（2026-09-26 用户实测踩坑）
        try:
            engine.start_server_watcher()
        except Exception:                                  # noqa: BLE001
            pass
        # ── ① 先读本地缓存点亮界面（不联网）──────────────────────────
        # 以前启动直接 build()：缓存超过 10 分钟( CACHE_TTL )就重下整包，这
        # 5~15 秒里 STATE["rewards"] 是空的 → 服务器列表每台都「未收录」，
        # 玩家以为数据没录（2026-10-28 用户反馈）。现在本地缓存先上桌，
        # 上游校准放后台，界面第一屏就是完整数据。
        try:
            m0 = engine.load_cached_state()
            log("step: 本地缓存已载入（%s 图 / %s 关，构建于 %s），后台再校准上游"
                % (m0.get("maps"), m0.get("stages"), m0.get("built_at_str", "?")))
        except Exception as e:                             # noqa: BLE001
            log("本地缓存不可用（%r），等待完整同步" % (e,))
        # ── ② 后台校准：缓存过期才下载，有变化才换代 ─────────────────
        try:
            meta = engine.load_state(force="--force" in args)
            log("step: 索引就绪 %s 图 / %s 关（构建于 %s）"
                % (meta.get("maps"), meta.get("stages"), meta.get("built_at_str", "?")))
            log("广播文件：%s（存在=%s）" % (engine.BROADCAST_FILE, os.path.exists(engine.BROADCAST_FILE)))
            srv = engine.current_server.detect(force=True)
            log("服务器定位：available=%s game=%s addr=%s map=%s query_ok=%s"
                % (srv.get("available"), srv.get("game_running"), srv.get("address"),
                   srv.get("map"), srv.get("query_ok")))
        except Exception as e:
            log("[!] 后台数据加载失败（页面轮询会持续重试）：%r" % e)
            log(traceback.format_exc())
        finally:
            # 无论成败都开闸：失败时若一直关着，/api/mapparams、/api/updlog
            # 会每次干等满超时，界面反而更卡
            engine.STATE_READY.set()

    threading.Thread(target=_boot_load, daemon=True, name="boot-load").start()
    # 预览壳地图名单预热（v2.14 性能）：壳 17MB、解析约 2 秒，以前每次冷启动都
    # 卡在地图库首个请求上。这里启动就解一遍并落盘缓存，玩家点开地图库时是
    # 直接读 20KB 名单，冷构建从 2.6 秒降到十几毫秒。
    def _pv_warm_boot():
        try:
            p = preview_path()
            if not p:
                return
            st = os.stat(p)
            if st.st_size <= 1024 * 1024:          # 壳还没下完，热身没有意义
                return
            tok = (p, st.st_mtime, st.st_size)
            if _pvnames_read_disk(tok) is None:
                _pvnames_warm(p, tok)
            else:
                log("[预览] 名单缓存命中（壳 %d MB）" % (st.st_size // 1048576))
        except Exception:                                      # noqa: BLE001
            pass

    threading.Thread(target=_pv_warm_boot, daemon=True, name="pvnames-boot").start()
    # 译名云端热更：起来后自己慢慢拉（失败静默，绝不影响界面）
    threading.Thread(target=mapnames_loop, daemon=True, name="mapnames").start()
    # 上游数据变更后台定时检测：每 30 分钟静默比对一次（失败静默，绝不弹窗打扰）
    threading.Thread(target=repo_check_loop, daemon=True, name="repo-check").start()

    srv = start_http_server(port)
    if srv is None:                    # 已有实例在跑：提示过用户了，安静退出
        return 0
    # GSI 的 cfg 里写着端口，而本机端口每次启动可能变（被占用会换）：
    # 开关是开着的话，每次启动都按当前端口重写一遍 cfg，玩家不用管。
    def _gsi_boot():
        try:
            if not gsi.enabled():
                return
            r = gsi.cfg_install(State.port)
            log("[GSI] 配置已写入（默认开启）：%s"
                % ("; ".join(r.get("dirs") or []) or r.get("error") or "未找到 CS2"))
            st = gsi.status_payload()
            if st.get("need_restart"):
                log("[GSI] CS2 正在运行，配置要重启游戏后才生效（本次会话收不到推送）")
        except Exception as e:                                 # noqa: BLE001
            log("[GSI] 启动写 cfg 失败：%r" % (e,))

    threading.Thread(target=_gsi_boot, daemon=True, name="gsi-boot").start()
    # 端口被占用时 start_http_server 会退回随机端口，所以以它实际绑定的为准
    port = State.port
    url = State.url
    if "--theme" in args:                      # 预览/固定主题，如 --theme N
        try:
            url += "?theme=" + str(args[args.index("--theme") + 1]).strip()[:1].upper()
        except IndexError:
            pass
    log("step: 本地服务已启动 %s" % url)

    if force_browser:
        return run_browser(url)

    try:
        import webview
        log("step: 已导入 pywebview")
    except Exception as e:
        log("[!] 未安装窗口组件（%s），改用兜底窗口。" % e)
        if run_edge_app(url):
            return
        return run_browser(url)

    # ── 原生启动卡（v2.15 批次）：WebView2 控件就绪前的空窗期，之前只有纯色底，
    # 用户看到「空白窗口数秒才见加载界面」。现在把与页面版 #bootSplash 同款同配色的
    # 启动卡用 GDI+ 直接画在窗体本体上（boot_native.patch 挂 BrowserForm.__init__），
    # 窗口出现的第一帧就是完整启动卡；WebView2 就绪后页面首帧无缝接管。
    try:
        _th = str(load_uiprefs().get("theme") or "E").strip().upper()[:1]
    except Exception:                                          # noqa: BLE001
        _th = "E"
    _boot_logo = None
    for _cand in (os.path.join(BASE_DIR, "logo_embed.png"),
                  os.path.join(getattr(sys, "_MEIPASS", BASE_DIR), "data", "logo_embed.png"),
                  os.path.join(BASE_DIR, "app.ico")):
        if os.path.exists(_cand):
            _boot_logo = _cand
            break
    try:
        import boot_native
        _boot_native_ok = boot_native.patch(APP_VER, _th, _boot_logo, logfn=log)
    except Exception as e:                                     # noqa: BLE001
        _boot_native_ok = False
        log("[!] 原生启动卡模块加载失败（%r）。" % e)

    try:
        State.win = webview.create_window(
            APP_TITLE_VER, url,
            width=win_w,
            height=win_h,
            min_size=(320, 140),
            resizable=True,
            frameless=True,          # 去掉系统标题栏，改用页面自绘（颜色随主题）
            easy_drag=False,         # 拖动走 /api/ctl?do=drag，只认页面标题栏
            background_color=("#1a1920" if _th == "N" else "#fff6f8"),
        )
        log("step: 窗口对象已创建（url 模式；原生启动卡 %s，页面启动卡随首帧接管，主题 %s）"
            % ("已挂" if _boot_native_ok else "未挂", _th))
    except Exception as e:
        log("[!] 创建窗口失败（%s），改用兜底窗口。" % e)
        log(traceback.format_exc())
        if run_edge_app(url):
            return
        return run_browser(url)

    # 最小化 → 系统任务栏（v2.7 起）：此前点最小化会 hide() 收进系统托盘，
    # 玩家反馈「点了最小化就找不着窗口了」，改回系统默认的最小化到任务栏行为。
    # 不再挂 win.events.minimized，也不再起托盘线程。

    log("step: 进入消息循环 webview.start()")
    try:
        webview.start(_probe, None)
        log("step: 消息循环已退出（窗口关闭）")
        ov_shutdown_on_exit()      # 覆盖小窗跟着退（拖动位置已随时落盘）
    except Exception as e:
        log("[!] 窗口运行异常（%s），改用兜底窗口。" % e)
        log(traceback.format_exc())
        if run_edge_app(url):
            return
        return run_browser(url)


def _apply_app_icon():
    """给主窗口设置品牌图标（任务栏 / Alt-Tab）。

    pywebview 不暴露图标参数，这里直接 Win32：EnumWindows 找到本进程
    可见主窗口，LoadImage 读 app.ico，SendMessage(WM_SETICON) 大小图标各一。
    """
    ICO = os.path.join(BASE_DIR, "app.ico")
    if not os.path.exists(ICO):
        return
    try:
        import ctypes
        from ctypes import wintypes

        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32
        IMAGE_ICON = 1
        LR_LOADFROMFILE = 0x10
        WM_SETICON = 0x0080
        ICON_SMALL, ICON_BIG = 0, 1
        GWL_EXSTYLE = -20
        WS_EX_TOOLWINDOW = 0x80

        def load(sz):
            return user32.LoadImageW(None, ICO, IMAGE_ICON, sz, sz, LR_LOADFROMFILE)

        found = []

        @ctypes.WINFUNCTYPE(ctypes.c_bool, wintypes.HWND, wintypes.LPARAM)
        def _cb(hwnd, _lp):
            pid = wintypes.DWORD()
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
            if pid.value != os.getpid():
                return True
            if not user32.IsWindowVisible(hwnd):
                return True
            ex = user32.GetWindowLongW(hwnd, GWL_EXSTYLE)
            if ex & WS_EX_TOOLWINDOW:
                return True
            found.append(hwnd)
            return False        # 已找到，停止枚举

        def find_hwnd(timeout=15.0):
            deadline = time.time() + timeout
            while time.time() < deadline:
                found.clear()
                user32.EnumWindows(_cb, 0)
                if found:
                    return found[0]
                time.sleep(0.4)
            return None

        hwnd = find_hwnd()
        if not hwnd:
            log("[!] 未找到主窗口句柄，任务栏图标未更新")
            return
        h_small, h_big = load(16), load(48)
        if h_small:
            user32.SendMessageW(hwnd, WM_SETICON, ICON_SMALL, h_small)
        if h_big:
            user32.SendMessageW(hwnd, WM_SETICON, ICON_BIG, h_big)
        log("step: 品牌图标已应用（app.ico → 窗口/任务栏）")
    except Exception as e:                                     # noqa: BLE001
        log("[!] 设置图标失败: %r" % e)


def _probe(*_):
    """窗口起来后先应用品牌图标，8 秒读回页面渲染状态写进日志。"""
    _apply_app_icon()
    time.sleep(8)
    win = State.win
    if win is None:
        return
    js = ("(function(){function t(id){var e=document.getElementById(id);"
          "return e?e.textContent:null;}"
          "return JSON.stringify({state:t('stateText'),map:t('mapName'),"
          "srv:t('srvName'),passes:t('bigVal'),"
          "pv:typeof window.pywebview,"
          "rows:document.querySelectorAll('#tbody tr').length});})()")
    # evaluate_js 是同步跨线程调用，页面忙或 WebView2 未就绪时可能长时间不返回。
    # 放到守护线程里带上限等待，超时就记一行跳过，避免探针把启动线程挂住。
    box = {}

    def _call():
        try:
            box["v"] = win.evaluate_js(js)
        except Exception:                                      # noqa: BLE001
            box["e"] = traceback.format_exc()

    t = threading.Thread(target=_call, daemon=True)
    t.start()
    t.join(6.0)
    if t.is_alive():
        log("探针(8s后) 跳过：evaluate_js 超过 6 秒未返回（页面忙或视图未就绪）")
    elif "e" in box:
        log("探针失败:\n" + box["e"])
    else:
        log("探针(8s后) 页面状态: %s" % box.get("v"))


# ── 解压目录自愈（v2.8）─────────────────────────────────────────────────
# PyInstaller 单文件版的**子进程会复用父进程的解压目录**：bootloader 用
# _PYI_PARENT_PROCESS_LEVEL / _PYI_APPLICATION_HOME_DIR 两个环境变量把「我是谁、
# 目录在哪」告诉子孙进程，子孙进程便不再自己解压（实测：覆盖小窗子进程不会新建
# _MEI 目录，直接复用主进程那份）。
#
# 一键更新恰好是「写 bat → 自己退出 → bat 替换 exe → start 起新 exe」，而 bat 是
# 旧进程的后代，**新 exe 因此继承了旧进程的解压目录**，后果有两个：
#   ① 跑的还是旧版代码（只是 exe 文件换新了，界面版本号仍是旧的）
#   ② 旧目录已被旧进程的 bootloader 递归删过一遍 —— x64 那份 WebView2Loader.dll
#      被运行中的进程占着删不掉，而 win-arm64 / win-x86 在 x64 机器上根本没人加载，
#      于是被删掉了；覆盖小窗一 import webview 就
#      FileNotFoundError('Cannot find win-arm64')（v2.6→v2.7 的真实故障）
# 所以进入主流程前先自检：目录不完整、或不是本 exe 解压出来的，就清掉继承来的标记
# 重启自己，让它作为顶层进程重新解压一份干净目录。
_MEI_STAMP = ".fys_exe_fp"


def _meipass_ok():
    """当前解压目录可用、且确实属于本 exe 时返回 True。"""
    if not getattr(sys, "frozen", False) or not getattr(sys, "_MEIPASS", None):
        return True                                    # 源码运行，不适用
    mp = sys._MEIPASS
    if not os.path.isdir(mp):
        return True
    try:
        # ① 三份 WebView2Loader.dll 缺一不可（pywebview 对三架构逐个无条件解析）
        for arch in ("win-arm64", "win-x64", "win-x86"):
            if not os.path.exists(os.path.join(
                    mp, "webview", "lib", "runtimes", arch, "native",
                    "WebView2Loader.dll")):
                return False
        # ② 指纹：这个目录是不是「当前这个 exe」解压出来的
        cur = "%d:%d" % (os.path.getsize(sys.executable),
                         int(os.path.getmtime(sys.executable)))
        stamp = os.path.join(mp, _MEI_STAMP)
        try:
            with open(stamp, encoding="utf-8") as fh:
                old = fh.read().strip()
        except OSError:
            old = ""
        if not old:                                    # 自己解压出来的，记一笔
            try:
                with open(stamp, "w", encoding="utf-8") as fh:
                    fh.write(cur)
            except OSError:
                pass
            return True
        return old == cur
    except Exception:                                  # noqa: BLE001
        return True                                    # 自检本身出错就别拦，照常启动


def _selfheal_meipass():
    """解压目录异常（更新后复用了旧版残留目录）→ 清标记后干净重启自己。"""
    if os.environ.get("FYS_MEI_HEALED"):               # 只治一次，避免反复重启
        return False
    try:
        if _meipass_ok():
            return False
    except Exception:                                  # noqa: BLE001
        return False
    env = dict(os.environ)
    for k in ("_PYI_PARENT_PROCESS_LEVEL", "_PYI_APPLICATION_HOME_DIR", "_MEIPASS"):
        env.pop(k, None)          # 清掉后新进程即是顶层，会自己解压干净目录
    env["FYS_MEI_HEALED"] = "1"
    log("自检：解压目录不属于本版本（更新后复用了旧目录）→ 重新启动一份干净实例")
    try:
        subprocess.Popen([sys.executable] + sys.argv[1:], env=env, cwd=BASE_DIR,
                         close_fds=True, creationflags=_NO_WINDOW)
    except Exception as e:                             # noqa: BLE001
        log("自检：重启失败 %r —— 按原样继续（可能缺 webview 组件）" % (e,))
        return False
    return True


def entry():
    try:
        if _selfheal_meipass():
            os._exit(0)
        main()
        return 0
    except Exception:
        tb = traceback.format_exc()
        log("FATAL 未捕获异常：\n" + tb)
        # 打包后 console=False，双击 exe 出错时用户只会看到「什么都没发生」。
        # 弹个原生消息框，至少告诉他日志在哪。
        try:
            import ctypes
            ctypes.windll.user32.MessageBoxW(
                None,
                "启动失败：\n\n%s\n\n完整日志：\n%s" % (tb.strip()[-1200:], LOG_PATH),
                APP_TITLE, 0x10)          # MB_ICONERROR
        except Exception:                                      # noqa: BLE001
            pass
        return 1


if __name__ == "__main__":
    raise SystemExit(entry())
